class InvalidFinalAggregateChainError(ValueError):
    """A final aggregate chain successor breaks its contract."""


def _fag_chain_invalid(message: str) -> InvalidFinalAggregateChainError:
    return InvalidFinalAggregateChainError(
        f"invalid final aggregate chain: {message}"
    )


def _reject_duplicate_fag_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate successor keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _fag_chain_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


# -- Stage views over a root final aggregate or a successor packet --------------

def _fag_root_view(raw: bytes) -> dict:
    """Structurally parse a root final aggregate predecessor."""
    payload, _signature = _parse_adcfda(raw)
    return {
        "kind": "root",
        _FAG_ROOT_DIGEST: hashlib.sha256(raw).hexdigest(),
        _FAG_HEIGHT: 0,
        STATUS: payload[STATUS],
        _ADCFDA_DECLARATION: payload[_ADCFDA_DECLARATION],
        _ADCFDA_INPUTS: list(payload[_ADCFDA_INPUTS]),
        PA_ITEMS: copy.deepcopy(payload[ITEMS]),
        "prune_policy_digest": payload[_ADCFDA_PRUNE_POLICY_DIGEST],
        "authorization_policy_digest": payload[
            _ADCFDA_AUTHORIZATION_POLICY_DIGEST
        ],
        "site_policy_digest": payload[_ADCFDA_SITE_POLICY_DIGEST],
        "signer_site_policy_digest": payload[
            _ADCFDA_SIGNER_SITE_POLICY_DIGEST
        ],
        "policy_digest": payload[_ADCFDA_DECISION_SITE_POLICY_DIGEST],
        _FAG_POLICY_VERSION:
            AGGREGATE_DECISION_CHAIN_FORK_DECISION_AGGREGATE_VERSION,
        _FAG_EFFECTIVE_AT: None,
    }


def _fag_successor_view(raw: bytes) -> dict:
    """Structurally parse a final aggregate successor predecessor."""
    payload, _signature, _increment = _fag_parse_successor(raw)
    return {
        "kind": "successor",
        _FAG_ROOT_DIGEST: payload[_FAG_ROOT_DIGEST],
        _FAG_HEIGHT: payload[_FAG_HEIGHT],
        STATUS: payload[STATUS],
        _ADCFDA_DECLARATION: copy.deepcopy(payload[_ADCFDA_DECLARATION]),
        _ADCFDA_INPUTS: list(payload[_ADCFDA_INPUTS]),
        PA_ITEMS: copy.deepcopy(payload[ITEMS]),
        "prune_policy_digest": payload[_ADCFDA_PRUNE_POLICY_DIGEST],
        "authorization_policy_digest": payload[
            _ADCFDA_AUTHORIZATION_POLICY_DIGEST
        ],
        "site_policy_digest": payload[_ADCFDA_SITE_POLICY_DIGEST],
        "signer_site_policy_digest": payload[
            _ADCFDA_SIGNER_SITE_POLICY_DIGEST
        ],
        "policy_digest": payload[_FAG_NEW_POLICY_DIGEST],
        _FAG_POLICY_VERSION: payload[_FAG_POLICY_VERSION],
        _FAG_EFFECTIVE_AT: payload[_FAG_EFFECTIVE_AT],
    }


def _fag_predecessor_view(raw: object) -> dict:
    """Parse predecessor bytes (root aggregate or successor packet).

    The packet kind is chosen from the payload key set so a malformed
    root raises
    :class:`InvalidAggregateDecisionChainForkDecisionAggregateError`
    while a malformed successor raises
    :class:`InvalidFinalAggregateChainError`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("predecessor must be bytes")
    keys = _packet_payload_keys(raw)
    if keys is not None and _FAG_ROOT_DIGEST in keys:
        return _fag_successor_view(raw)
    return _fag_root_view(raw)


# -- Recomputing one stage verdict from prefix plus decision increment ---------

def _fag_recompute(
    prefix_inputs: list[str],
    prefix_rows: list[dict],
    increment: list[dict],
    prune_policy_digest: str,
    authorization_policy_digest: str,
    site_policy_digest: str,
    signer_site_policy_digest: str,
    fork_threshold: int,
    decision_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Recompute the complete stage conclusion from prefix plus increment.

    The prefix statements are the already-verified statements of the
    predecessor; each new decision is authenticated and authorized
    through the existing aggregate decision chain fork decision
    aggregate rules under the new decision site policy, and the complete
    statement set is re-tallied with the prefix statements always
    winning over a newly appended repeat.
    """
    increment_rows: list[dict] = []
    increment_digests: list[str] = []
    for item in increment:
        raw = item[_FAG_PACKET]
        increment_digests.append(hashlib.sha256(raw).hexdigest())
        increment_rows.append(
            _aggregate_adcfda_one(
                item,
                prune_policy_digest,
                authorization_policy_digest,
                site_policy_digest,
                signer_site_policy_digest,
                fork_threshold,
                decision_site_policy,
                validated_keyring,
                moment,
            )
        )

    full_inputs = list(prefix_inputs) + increment_digests
    working_rows = copy.deepcopy(prefix_rows)
    working_rows.extend(copy.deepcopy(increment_rows))
    status, declaration = _cfca_tally_chain_rows(
        working_rows, len(prefix_rows), decision_site_policy[ADJ_THRESHOLD]
    )
    return {
        _ADCFDA_INPUTS: full_inputs,
        PA_ITEMS: _pac_sort_rows(working_rows),
        STATUS: status,
        _ADCFDA_DECLARATION: declaration,
    }


def _fag_assert_extends(
    previous: dict, full_inputs: list[str], increment: list[dict],
    unchanged: bool,
) -> None:
    """Enforce the append-only decision prefix and disjoint identities.

    The predecessor's decision digests must remain the ordered prefix of
    the stage -- nothing is deleted, changed or reordered -- and a
    non-empty increment adds only new packet digests and new item ids.
    An unchanged policy must add at least one decision; a rotation may
    re-seal the identical sequence with an empty increment.
    """
    prefix_inputs = previous[_ADCFDA_INPUTS]
    if unchanged and not increment:
        raise _fag_chain_invalid("an unchanged policy requires new decisions")
    if len(full_inputs) < len(prefix_inputs):
        raise _fag_chain_invalid(
            "the decision sequence must extend the predecessor"
        )
    if full_inputs[:len(prefix_inputs)] != prefix_inputs:
        raise _fag_chain_invalid(
            "the decision sequence must keep the predecessor as an ordered "
            "prefix; history must not be deleted, changed or reordered"
        )
    prefix_digests = set(prefix_inputs)
    prefix_ids = {row[ID] for row in previous[PA_ITEMS]}
    seen_digests: set[str] = set()
    seen_ids: set[str] = set()
    for item in increment:
        digest = hashlib.sha256(item[_FAG_PACKET]).hexdigest()
        if digest in prefix_digests or digest in seen_digests:
            raise _fag_chain_invalid(
                "a decision packet already in the prefix must not be "
                "appended again"
            )
        seen_digests.add(digest)
        item_id = item[ID]
        if item_id in prefix_ids or item_id in seen_ids:
            raise _fag_chain_invalid(
                f"decision item id {item_id!r} is already part of the chain"
            )
        seen_ids.add(item_id)


def _fag_assert_transition(previous: dict, verdict: dict) -> None:
    """Enforce the per-hop verdict state machine for a final aggregate.

    ``insufficient`` may gain supplemental decisions and become
    ``accepted`` or ``conflicted``; an ``accepted`` head only keeps the
    identical common declaration or advances to ``conflicted`` (it
    never falls back to insufficient or swaps declarations); a
    ``conflicted`` verdict can never be masked by a later majority.
    """
    prev_status = previous[STATUS]
    new_status = verdict[STATUS]
    if prev_status == PA_STATUS_CONFLICTED:
        if new_status != PA_STATUS_CONFLICTED:
            raise _fag_chain_invalid(
                "a conflicted aggregate can never be outvoted or fall back"
            )
    elif prev_status == PA_STATUS_ACCEPTED:
        if new_status == PA_STATUS_INSUFFICIENT:
            raise _fag_chain_invalid(
                "an accepted aggregate must not fall back to insufficient"
            )
        if new_status == PA_STATUS_ACCEPTED:
            if verdict[_ADCFDA_DECLARATION] != previous[_ADCFDA_DECLARATION]:
                raise _fag_chain_invalid(
                    "an accepted aggregate may only keep the same common "
                    "declaration"
                )


def _fag_assert_sealer_authorized(
    old_policy: dict, new_policy: dict, issuer: str, key_version: int
) -> None:
    """The successor sealer must be authorized under both site policies."""
    if key_version not in old_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _fag_chain_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the previous site policy"
        )
    if key_version not in new_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _fag_chain_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the rotated site policy"
        )


# -- Successor packet shape ----------------------------------------------------

def _fag_bound_decisions(raw_items: object, where: str) -> list[dict]:
    """Parse the raw decision increment bound inside a successor packet."""
    if not isinstance(raw_items, list):
        raise TypeError(f"{where} decisions must be a list")
    validated: list[dict] = []
    for position, item in enumerate(raw_items):
        item_where = f"{where} decision {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{item_where} must be an object")
        if set(item.keys()) != _FAG_DECISION_ITEM_KEYS:
            raise _fag_chain_invalid(
                f"{item_where} must contain exactly the keys 'decision' and "
                "'id'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{item_where} id must be a str")
        if item_id == "":
            raise _fag_chain_invalid(f"{item_where} id must be non-empty")
        packet_hex = item[_FAG_PACKET]
        if not isinstance(packet_hex, str):
            raise TypeError(f"{item_where} decision must be a str")
        try:
            packet = _hex_bytes(packet_hex)
        except ValueError as exc:
            raise _fag_chain_invalid(
                f"{item_where} decision must be non-empty even-length "
                "lowercase hex"
            ) from exc
        validated.append({ID: item_id, _FAG_PACKET: packet})
    return validated


def _fag_validated_rows(raw_rows: object, where: str) -> list[dict]:
    """Validate the bound aggregate rows of a chain successor payload.

    The row contract is the one
    :func:`aggregate_aggregate_decision_chain_fork_decisions` binds; a
    counted row's complete declaration keeps the term-by-term proof
    digest vector of a legal aggregate decision chain fork decision and
    may carry the empty common fork edge set.  A wrong JSON type raises
    :class:`TypeError` and every other structural fault raises
    :class:`InvalidFinalAggregateChainError`.
    """
    if not isinstance(raw_rows, list):
        raise TypeError(f"{where} items must be a list")
    if not raw_rows:
        raise _fag_chain_invalid(f"{where} items must be a non-empty list")
    parsed_rows: list[dict] = []
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        row_where = f"{where} item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be an object")
        if set(row.keys()) != _PFDA_ROW_KEYS:
            raise _fag_chain_invalid(
                f"{row_where} must contain exactly the keys 'conclusion', "
                "'digest', 'id', 'issuer', 'keyVersion', 'reason' and "
                "'declaration'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{row_where} id must be a str")
        if row_id == "":
            raise _fag_chain_invalid(f"{row_where} id must be non-empty")
        if row_id in seen_ids:
            raise _fag_chain_invalid(f"{row_where} repeats an id")
        seen_ids.add(row_id)
        digest = row[CP_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{row_where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _fag_chain_invalid(
                f"{row_where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None and not isinstance(site, str):
            raise TypeError(f"{row_where} issuer must be a str or null")
        if site == "":
            raise _fag_chain_invalid(f"{row_where} issuer must be non-empty")
        key_version = row[KEY_VERSION]
        if isinstance(key_version, bool) or not isinstance(key_version, int):
            if key_version is not None:
                raise TypeError(
                    f"{row_where} keyVersion must be an int or null"
                )
        elif key_version <= 0:
            raise _fag_chain_invalid(
                f"{row_where} keyVersion must be positive"
            )
        if (site is None) != (key_version is None):
            raise _fag_chain_invalid(
                f"{row_where} issuer and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{row_where} conclusion must be a str")
        reason = row[ADJ_REASON]
        if conclusion == PA_CONCLUSION_VALID:
            if reason is not None:
                raise _fag_chain_invalid(
                    f"{row_where} reason must be null for a valid row"
                )
        elif conclusion == PA_CONCLUSION_INVALID:
            if reason not in _PFDA_INVALID_REASONS:
                raise _fag_chain_invalid(
                    f"{row_where} reason must be one of 'invalid', "
                    "'unauthenticated' or 'unauthorized'"
                )
        elif conclusion in (
            PA_CONCLUSION_DUPLICATE, PA_CONCLUSION_CONTRADICTION
        ):
            expected = (
                REASON_DUPLICATE
                if conclusion == PA_CONCLUSION_DUPLICATE
                else REASON_CONTRADICTION
            )
            if reason != expected:
                raise _fag_chain_invalid(
                    f"{row_where} reason must match its conclusion"
                )
        else:
            raise _fag_chain_invalid(f"{row_where} conclusion is not known")
        identity_present = reason != PA_CONCLUSION_INVALID
        if identity_present:
            if site is None:
                raise _fag_chain_invalid(
                    f"{row_where} an authenticated or authorized row must "
                    "carry its issuer"
                )
        elif site is not None:
            raise _fag_chain_invalid(
                f"{row_where} an invalid row must carry no issuer"
            )
        if conclusion == PA_CONCLUSION_INVALID:
            if row[_ADCFDA_DECLARATION] is not None:
                raise _fag_chain_invalid(
                    f"{row_where} an invalid row must carry no declaration"
                )
            declaration = None
        else:
            try:
                declaration = _validated_pfda_declaration(
                    row[_ADCFDA_DECLARATION], f"{row_where} declaration",
                    invalid=_adcfda_invalid, positional_proofs=True,
                    allow_empty_edges=True,
                )
            except InvalidAggregateDecisionChainForkDecisionAggregateError \
                    as exc:
                raise _fag_chain_invalid(str(exc)) from exc
            if declaration is None:
                raise _fag_chain_invalid(
                    f"{row_where} a counted row must carry its declaration"
                )
        parsed_rows.append({
            ADJ_CONCLUSION: conclusion,
            CP_DIGEST: digest,
            ID: row_id,
            VD_ISSUER: site,
            KEY_VERSION: key_version,
            ADJ_REASON: reason,
            _ADCFDA_DECLARATION: declaration,
        })
    return parsed_rows


def _fag_parse_successor(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate successor bytes into ``(payload, signature, increment)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, row or increment fault raises
    :class:`InvalidFinalAggregateChainError`.  The predecessor, policy,
    moment, tally and signature bindings are checked by the chain
    verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("successor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _fag_chain_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _fag_chain_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_fag_keys
        )
    except json.JSONDecodeError as exc:
        raise _fag_chain_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("successor must be a JSON object")
    if set(data.keys()) != _FAG_TOP_KEYS:
        raise _fag_chain_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("successor signature must be a str")
    if not _prune_is_digest(signature):
        raise _fag_chain_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("successor payload must be an object")
    if set(payload.keys()) != _FAG_SUCCESSOR_PAYLOAD_KEYS:
        raise _fag_chain_invalid("payload must contain exactly the bound keys")

    for key in (
        _FAG_ROOT_DIGEST, _FAG_PREDECESSOR_DIGEST,
        _ADCFDA_PRUNE_POLICY_DIGEST, _ADCFDA_AUTHORIZATION_POLICY_DIGEST,
        _ADCFDA_SITE_POLICY_DIGEST, _ADCFDA_SIGNER_SITE_POLICY_DIGEST,
        _FAG_OLD_POLICY_DIGEST, _FAG_NEW_POLICY_DIGEST,
    ):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _fag_chain_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[_FAG_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 1:
        raise _fag_chain_invalid("payload height must be a positive integer")
    policy_version = payload[_FAG_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _fag_chain_invalid("payload policyVersion must be positive")
    effective = payload[_FAG_EFFECTIVE_AT]
    if isinstance(effective, bool) or not isinstance(effective, int):
        raise TypeError("payload effectiveAt must be an int")
    if effective < 0:
        raise _fag_chain_invalid("payload effectiveAt must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _fag_chain_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _fag_chain_invalid("payload keyVersion must be positive")
    packet_version = payload[VERSION]
    if isinstance(packet_version, bool) or not isinstance(
        packet_version, int
    ):
        raise TypeError("payload version must be an int")
    if packet_version != FINAL_AGGREGATE_CHAIN_VERSION:
        raise _fag_chain_invalid("payload version must be the integer 1")

    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PA_STATUSES:
        raise _fag_chain_invalid("payload status is not known")

    inputs = payload[_ADCFDA_INPUTS]
    if not isinstance(inputs, list):
        raise TypeError("payload inputs must be a list")
    if not inputs:
        raise _fag_chain_invalid("payload inputs must be a non-empty list")
    for position, digest in enumerate(inputs):
        if not isinstance(digest, str):
            raise TypeError(f"payload input {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _fag_chain_invalid(
                f"payload input {position} digest must be 64 lowercase hex "
                "characters"
            )

    rows = _fag_validated_rows(payload[ITEMS], "payload")
    if len(rows) != len(inputs):
        raise _fag_chain_invalid(
            "the items must cover every decision and vice versa"
        )
    raw_declaration = payload[_ADCFDA_DECLARATION]
    if raw_declaration is None:
        declaration = None
    else:
        try:
            declaration = _validated_pfda_declaration(
                raw_declaration, "payload declaration",
                invalid=_adcfda_invalid, positional_proofs=True,
                allow_empty_edges=True,
            )
        except InvalidAggregateDecisionChainForkDecisionAggregateError as exc:
            raise _fag_chain_invalid(str(exc)) from exc
    if status == PA_STATUS_ACCEPTED and declaration is None:
        raise _fag_chain_invalid(
            "an accepted verdict must keep the common declaration"
        )
    if status == PA_STATUS_CONFLICTED and declaration is not None:
        raise _fag_chain_invalid(
            "a conflicted verdict must bind a null common declaration"
        )

    increment = _fag_bound_decisions(payload[_FAG_DECISIONS], "payload")

    normalized_payload = {
        _FAG_ROOT_DIGEST: payload[_FAG_ROOT_DIGEST],
        _FAG_PREDECESSOR_DIGEST: payload[_FAG_PREDECESSOR_DIGEST],
        _FAG_HEIGHT: height,
        _ADCFDA_INPUTS: list(inputs),
        ITEMS: rows,
        _ADCFDA_DECLARATION: declaration,
        STATUS: status,
        _ADCFDA_PRUNE_POLICY_DIGEST: payload[_ADCFDA_PRUNE_POLICY_DIGEST],
        _ADCFDA_AUTHORIZATION_POLICY_DIGEST: payload[
            _ADCFDA_AUTHORIZATION_POLICY_DIGEST
        ],
        _ADCFDA_SITE_POLICY_DIGEST: payload[_ADCFDA_SITE_POLICY_DIGEST],
        _ADCFDA_SIGNER_SITE_POLICY_DIGEST: payload[
            _ADCFDA_SIGNER_SITE_POLICY_DIGEST
        ],

def _pac_chain_materials(validated_items: list[dict]) -> list[dict]:
    """Digest summary of every input chain, strictly in input order."""
    return [
        {
            ID: item[ID],
            PAC_BATCH_ROOT: hashlib.sha256(item[PAC_BATCH_ROOT]).hexdigest(),
            PAC_BATCH_SUCCESSORS: [
                hashlib.sha256(successor).hexdigest()
                for successor in item[PAC_BATCH_SUCCESSORS]
            ],
            PAC_BATCH_POLICIES: [
                _pac_policy_digest(validated_policy)
                for validated_policy in _pac_validated_policy_sequence(
                    item[PAC_BATCH_POLICIES]
                )
            ],
        }
        for item in validated_items
    ]


def _validated_pac_fork_chains(chains: object, invalid=_pac_fork_proof_invalid):
    """Validate the bound chain material summary into fresh ordered dicts.

    Each entry must carry exactly ``id`` (a non-empty str, unique across
    the summary), ``root`` (the chain root's digest), ``successors``
    (the ordered successor digests, possibly empty) and ``policies``
    (the per-stage policy digests, exactly one more than the
    successors).  A field of the wrong type raises :class:`TypeError`;
    every key-set, value-format or count fault is raised through
    ``invalid`` (the prune aggregate fork proof error by default).
    """
    if not isinstance(chains, list):
        raise TypeError("payload chains must be a list")
    if not chains:
        raise invalid("payload chains must be non-empty")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, chain in enumerate(chains):
        where = f"chain {position}"
        if not isinstance(chain, dict):
            raise TypeError(f"{where} must be an object")
        if set(chain.keys()) != _PAC_FORK_CHAIN_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'id', 'policies', "
                "'root' and 'successors'"
            )
        chain_id = chain[ID]
        if not isinstance(chain_id, str):
            raise TypeError(f"{where} id must be a str")
        if chain_id == "":
            raise invalid(
                f"{where} id must be a non-empty str"
            )
        if chain_id in seen_ids:
            raise invalid(f"{where} repeats an id")
        seen_ids.add(chain_id)
        root = chain[PAC_BATCH_ROOT]
        if not isinstance(root, str):
            raise TypeError(f"{where} root must be a str")
        if not _prune_is_digest(root):
            raise invalid(
                f"{where} root must be 64 lowercase hex characters"
            )
        successors = chain[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        for hop_index, successor in enumerate(successors):
            if not isinstance(successor, str):
                raise TypeError(f"{where} successor {hop_index} must be a str")
            if not _prune_is_digest(successor):
                raise invalid(
                    f"{where} successor {hop_index} must be 64 lowercase hex "
                    "characters"
                )
        policies = chain[PAC_BATCH_POLICIES]
        if not isinstance(policies, list):
            raise TypeError(f"{where} policies must be a list")
        if not policies:
            raise invalid(
                f"{where} policies must be non-empty"
            )
        for policy_index, policy_digest in enumerate(policies):
            if not isinstance(policy_digest, str):
                raise TypeError(
                    f"{where} policy {policy_index} must be a str"
                )
            if not _prune_is_digest(policy_digest):
                raise invalid(
                    f"{where} policy {policy_index} must be 64 lowercase hex "
                    "characters"
                )
        if len(policies) != len(successors) + 1:
            raise invalid(
                f"{where} policies must provide one entry per chain stage "
                "(one more than the number of successors)"
            )
        validated.append({
            ID: chain_id,
            PAC_BATCH_ROOT: root,
            PAC_BATCH_SUCCESSORS: list(successors),
            PAC_BATCH_POLICIES: list(policies),
        })
    return validated


def _validated_pac_fork_chain_result(
    result: object, chain: dict, where: str,
    invalid=_pac_fork_proof_invalid,
) -> None:
    """Validate one verified chain summary against its chain material.

    The summary must follow the exact single-chain verification result
    shape of the fork batch the proof was issued over and every digest
    and the height must match the bound chain material.  A field of the
    wrong type raises :class:`TypeError` (a :class:`bool` never poses as
    an int); every key-set, value-format or binding fault is raised
    through ``invalid`` (the prune aggregate fork proof error by
    default).
    """
    if set(result.keys()) != _PAC_CHAIN_RESULT_KEYS:
        raise invalid(
            f"{where} result must contain exactly the keys 'commonDigest', "
            "'headDigest', 'height', 'policyVersion', 'rootDigest' and "
            "'status'"
        )
    root_digest = result[PAC_ROOT_DIGEST]
    if not isinstance(root_digest, str):
        raise TypeError(f"{where} result rootDigest must be a str")
    if not _prune_is_digest(root_digest):
        raise invalid(
            f"{where} result rootDigest must be 64 lowercase hex characters"
        )
    if root_digest != chain[PAC_BATCH_ROOT]:
        raise invalid(
            f"{where} result rootDigest does not match the chain material"
        )
    head_digest = result[PAC_HEAD_DIGEST]
    if not isinstance(head_digest, str):
        raise TypeError(f"{where} result headDigest must be a str")
    if not _prune_is_digest(head_digest):
        raise invalid(
            f"{where} result headDigest must be 64 lowercase hex characters"
        )
    successors = chain[PAC_BATCH_SUCCESSORS]
    expected_head = successors[-1] if successors else chain[PAC_BATCH_ROOT]
    if head_digest != expected_head:
        raise invalid(
            f"{where} result headDigest does not match the chain material"
        )
    height = result[PAC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError(f"{where} result height must be an int")
    if height != len(successors):
        raise invalid(
            f"{where} result height does not match the chain material"
        )
    policy_version = result[PAC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError(f"{where} result policyVersion must be an int")
    if policy_version <= 0:
        raise invalid(
            f"{where} result policyVersion must be positive"
        )
    status = result[STATUS]
    if not isinstance(status, str):
        raise TypeError(f"{where} result status must be a str")
    if status not in _PAC_CHAIN_RESULT_STATUSES:
        raise invalid(
            f"{where} result status is not a known stage status"
        )
    common_digest = result[PAC_COMMON_DIGEST]
    if common_digest is not None:
        if not isinstance(common_digest, str):
            raise TypeError(f"{where} result commonDigest must be a str")
        if not _prune_is_digest(common_digest):
            raise invalid(
                f"{where} result commonDigest must be 64 lowercase hex "
                "characters"
            )


def _validated_pac_fork_report(
    report: object, chains: list[dict], *,
    conflicted_error=_PAC_CHAIN_ITEM_ERROR,
    invalid=_pac_fork_proof_invalid,
    report_version=PRUNE_AGGREGATE_CHAINS_VERSION,
    require_fork: bool = True,
) -> None:
    """Validate the complete chain-batch report bound into a fork proof.

    The report must follow the exact fork-chain batch report shape --
    ``forks``, ``items`` and ``version`` (the integer 1) -- with, by
    default, at least one fork.  Every binding to the chain material
    summary is checked: the item count and per-position ids, each
    verified result's digests and height, and each fork's exact forking
    successors and crossing chains recomputed from the bound materials.
    ``conflicted_error`` names the fixed error a conflicted item must
    carry.  ``require_fork`` is ``False`` for the aggregate decision
    chain layer, whose signed proofs may attest a fork-free batch with
    the fork collection bound empty.  A field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    key-set, value, ordering, reference or binding fault is raised
    through ``invalid``.
    """
    if not isinstance(report, dict):
        raise TypeError("payload report must be an object")
    if set(report.keys()) != _PAC_FORK_REPORT_KEYS:
        raise invalid(
            "bound report must contain exactly the keys 'forks', 'items' "
            "and 'version'"
        )
    version = report[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("bound report version must be an int")
    if version != report_version:
        raise invalid(
            "bound report version must be the integer 1"
        )

    items = report[ITEMS]
    if not isinstance(items, list):
        raise TypeError("bound report items must be a list")
    if not items:
        raise invalid("bound report items must be non-empty")
    if len(items) != len(chains):
        raise invalid(
            "bound report item count does not match the chain materials"
        )

    seen_ids: set[str] = set()
    for position, item_report in enumerate(items):
        where = f"bound report item {position}"
        if not isinstance(item_report, dict):
            raise TypeError(f"{where} must be an object")
        if set(item_report.keys()) != _PAC_FORK_ITEM_REPORT_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'error', 'id', "
                "'result' and 'status'"
            )
        item_id = item_report[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise invalid(
                f"{where} id must be a non-empty str"
            )
        if item_id != chains[position][ID]:
            raise invalid(
                f"{where} id does not match the chain material at its position"
            )
        if item_id in seen_ids:
            raise invalid(f"{where} repeats an id")
        seen_ids.add(item_id)
        status = item_report[STATUS]
        if not isinstance(status, str):
            raise TypeError(f"{where} status must be a str")
        if status not in _PAC_FORK_REPORT_STATUSES:
            raise invalid(
                f"{where} status is not a known status"
            )
        error = item_report[CHECKPOINT_ITEM_ERROR]
        result = item_report[VERDICT_ITEM_RESULT]
        if status == PAC_CHAINS_VERIFIED:
            if error is not None:
                raise invalid(
                    f"{where} error must be null when verified"
                )
            if not isinstance(result, dict):
                raise TypeError(
                    f"{where} result must be an object when verified"
                )
        elif status == PAC_CHAINS_CONFLICTED:
            if not isinstance(error, str):
                raise TypeError(f"{where} error must be a str when conflicted")
            if error != conflicted_error:
                raise invalid(
                    f"{where} error must be {conflicted_error!r} when "
                    "conflicted"
                )
            if not isinstance(result, dict):
                raise TypeError(
                    f"{where} result must be an object when conflicted"
                )
        else:
            if not isinstance(error, str):
                raise TypeError(f"{where} error must be a str for a failure")
            if error == "":
                raise invalid(
                    f"{where} error must be a non-empty str for a failure"
                )
            if result is not None:
                raise invalid(
                    f"{where} result must be null for a failure"
                )
        if isinstance(result, dict):
            _validated_pac_fork_chain_result(
                result, chains[position], where, invalid=invalid
            )

    forks = report[CHAINS_FORKS]
    if not isinstance(forks, list):
        raise TypeError("bound report forks must be a list")
    if require_fork and not forks:
        raise invalid(
            "a fork proof must report at least one fork"
        )

    # Recompute every edge from the bound materials over the items that
    # verified, then demand the bound fork entries match exactly -- the
    # same grouping and fork rule the fork-chain batch uses.
    groups: dict[str, dict[str, set[str]]] = {}
    for chain, item_report in zip(chains, items):
        if not isinstance(item_report[VERDICT_ITEM_RESULT], dict):
            continue
        nodes = [chain[PAC_BATCH_ROOT]] + chain[PAC_BATCH_SUCCESSORS]
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    expected_edges: dict[tuple[str, str], set[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                expected_edges[(root_digest, upstream)] = digests
    crossing: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in expected_edges
    }
    for chain, item_report in zip(chains, items):
        if not isinstance(item_report[VERDICT_ITEM_RESULT], dict):
            continue
        nodes = [chain[PAC_BATCH_ROOT]] + chain[PAC_BATCH_SUCCESSORS]
        for upstream in nodes[:-1]:
            edge = (nodes[0], upstream)
            if edge in expected_edges:
                crossing[edge].add(chain[ID])

    seen_edges: set[tuple[str, str]] = set()
    previous_edge: tuple[str, str] | None = None
    for position, fork in enumerate(forks):
        where = f"bound report fork {position}"
        if not isinstance(fork, dict):
            raise TypeError(f"{where} must be an object")
        if set(fork.keys()) != _PAC_CHAIN_FORK_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'ids', "
                "'predecessorDigest', 'rootDigest' and 'successors'"
            )
        root_digest = fork[PAC_ROOT_DIGEST]
        predecessor = fork[PAC_PREDECESSOR_DIGEST]
        if not isinstance(root_digest, str):
            raise TypeError(f"{where} rootDigest must be a str")
        if not isinstance(predecessor, str):
            raise TypeError(f"{where} predecessorDigest must be a str")
        if not _prune_is_digest(root_digest):
            raise invalid(
                f"{where} rootDigest must be 64 lowercase hex characters"
            )
        if not _prune_is_digest(predecessor):
            raise invalid(
                f"{where} predecessorDigest must be 64 lowercase hex "
                "characters"
            )
        edge = (root_digest, predecessor)
        if edge in seen_edges:
            raise invalid(f"{where} repeats a fork edge")
        seen_edges.add(edge)
        if previous_edge is not None and edge < previous_edge:
            raise invalid(
                f"{where} forks must be sorted by rootDigest then "
                "predecessorDigest"
            )
        previous_edge = edge
        if edge not in expected_edges:
            raise invalid(
                f"{where} is not a fork in the bound chain materials"
            )
        successors = fork[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        if any(not isinstance(successor, str) for successor in successors):
            raise TypeError(f"{where} successors must be strs")
        if any(not _prune_is_digest(successor) for successor in successors):
            raise invalid(
                f"{where} successors must be 64 lowercase hex characters"
            )
        if successors != sorted(successors) or len(set(successors)) != len(
            successors
        ):
            raise invalid(
                f"{where} successors must be unique and sorted ascending"
            )
        if set(successors) != expected_edges[edge]:
            raise invalid(
                f"{where} successors do not match the forking edge"
            )
        ids = fork[_FORK_IDS]
        if not isinstance(ids, list):
            raise TypeError(f"{where} ids must be a list")
        if any(not isinstance(fork_id, str) for fork_id in ids):
            raise TypeError(f"{where} ids must be strs")
        if any(fork_id == "" for fork_id in ids):
            raise invalid(f"{where} ids must be non-empty")
        if ids != sorted(ids) or len(set(ids)) != len(ids):
            raise invalid(
                f"{where} ids must be unique and sorted ascending"
            )
        if set(ids) != crossing[edge]:
            raise invalid(
                f"{where} ids do not match the chains crossing the edge"
            )

    if seen_edges != set(expected_edges):
        raise invalid(
            "the bound forks do not match the forking edges in the materials"
        )
    conflicted = {
        item_report[ID]
        for item_report in items
        if item_report[STATUS] == PAC_CHAINS_CONFLICTED
    }
    all_fork_ids: set[str] = set()
    for edge_crossing in crossing.values():
        all_fork_ids |= edge_crossing
    if conflicted != all_fork_ids:
        raise invalid(
            "the fork id sets must equal the conflicted report items"
        )


def _parse_pac_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate fork proof bytes into ``(payload, signature, chains)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, count, ordering, reference or
    report-binding fault raises
    :class:`InvalidAggregateForkProofError`.  The policy, moment,
    credential and signature bindings are checked by
    :func:`verify_prune_aggregate_fork_proof`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("proof must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _pac_fork_proof_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _pac_fork_proof_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_pac_fork_proof_keys
        )
    except json.JSONDecodeError as exc:
        raise _pac_fork_proof_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("proof must be a JSON object")
    if set(data.keys()) != _PAC_FORK_PROOF_TOP_KEYS:
        raise _pac_fork_proof_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("proof signature must be a str")
    if not _prune_is_digest(signature):
        raise _pac_fork_proof_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("proof payload must be an object")
    if set(payload.keys()) != _PAC_FORK_PROOF_PAYLOAD_KEYS:
        raise _pac_fork_proof_invalid(
            "payload must contain exactly the keys 'chains', 'issuer', "
            "'keyVersion', 'moment', 'policy', 'report' and 'version'"
        )
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _pac_fork_proof_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _pac_fork_proof_invalid("payload keyVersion must be positive")
    moment = payload[CP_MOMENT]
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("payload moment must be an int")
    if moment < 0:
        raise _pac_fork_proof_invalid("payload moment must be non-negative")
    policy_digest = payload[RECEIPT_POLICY]
    if not isinstance(policy_digest, str):
        raise TypeError("payload policy must be a str")
    if not _prune_is_digest(policy_digest):
        raise _pac_fork_proof_invalid(
            "payload policy must be 64 lowercase hex characters"
        )
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("payload version must be an int")
    if version != PRUNE_AGGREGATE_FORK_PROOF_VERSION:
        raise _pac_fork_proof_invalid("payload version must be the integer 1")
    chains = _validated_pac_fork_chains(payload[FORK_PROOF_CHAINS])
    _validated_pac_fork_report(payload[FORK_PROOF_REPORT], chains)

    if _prune_compact(data) != raw:
        raise _pac_fork_proof_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature, chains


def sign_prune_aggregate_fork_proof(
    items, prune_policy, keyring, moment, issuer, version
):
    """Sign the fork summary of a prune aggregate chain batch.

    ``items`` is the same non-empty list of ``{"id", "root",
    "successors", "policies"}`` dicts
    :func:`verify_prune_aggregate_chains` takes; ``prune_policy`` is
    the shared invariant original pruning policy, ``keyring`` follows
    the existing rules, ``moment`` is the signing time and
    ``issuer``/``version`` name the signing credentials.  The batch
    first runs through the exact :func:`verify_prune_aggregate_chains`
    rules and the proof is issued only when the resulting report
    records at least one fork.  No file is read or written and no
    argument is modified.

    The proof is one canonical compact UTF-8 JSON object -- every
    object key recursively sorted, non-ASCII preserved, no trailing
    newline or any other trailing byte -- carrying exactly ``payload``
    and ``signature``.  The payload binds exactly ``chains``,
    ``issuer``, ``keyVersion``, ``moment``, ``policy`` (the lowercase
    hex SHA-256 of the canonical compact prune policy encoding),
    ``report`` (the complete chain-batch report) and ``version`` (the
    integer 1).  ``chains`` summarizes every input chain, strictly in
    input order with no reordering, omission or replacement: each entry
    carries exactly ``id``, ``root`` (the SHA-256 of the chain's root
    bytes), ``successors`` (the SHA-256 of each successor's complete
    bytes in chain order) and ``policies`` (the SHA-256 of each stage
    policy's canonical bytes in history order).  ``signature`` is the
    lowercase hex HMAC-SHA256 of the canonical compact payload bytes
    under the key the keyring binds to the exact issuer and version,
    with no fallback.

    A parameter or public field type fault raises :class:`TypeError`
    (a :class:`bool` never poses as an int); an empty list, an empty or
    duplicate id, a wrong policy count, an empty issuer, a non-positive
    version, a negative moment, an illegal shared policy value or a
    report without a fork raises :class:`ValueError`; and unknown,
    revoked, not-yet-valid or expired credentials raise
    :class:`AuthenticationError`.
    """
    validated_items = _validated_pac_chain_batch(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_keyring = _validated_keyring(keyring)
    sign_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_prune_aggregate_chains(
        validated_items, prune_policy, keyring, sign_moment
    )
    if not report[CHAINS_FORKS]:
        raise ValueError(
            "a prune aggregate fork proof requires at least one fork in "
            "the chain report"
        )
    entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, sign_moment
    )
    payload = {
        FORK_PROOF_CHAINS: _pac_chain_materials(validated_items),
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        CP_MOMENT: sign_moment,
        RECEIPT_POLICY: hashlib.sha256(
            _verdict_policy_bytes(validated_prune_policy)
        ).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(report),
        VERSION: PRUNE_AGGREGATE_FORK_PROOF_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _verify_pac_fork_proof_core(
    raw: bytes,
    validated_prune_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one fork proof against already-validated shared materials.

    This is the shared core of :func:`verify_prune_aggregate_fork_proof`
    and the batch :func:`verify_prune_aggregate_fork_proofs`; the caller
    owns the argument-type and shared-material validation.  The returned
    dict is freshly built solely from authenticated proof material.
    """
    payload, signature, chains = _parse_pac_fork_proof(raw)
    recomputed_policy = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[RECEIPT_POLICY] != recomputed_policy:
        raise _pac_fork_proof_invalid(
            "policy digest does not match the policy"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _pac_fork_proof_invalid(
            "moment must not be later than the verification moment"
        )

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "prune aggregate fork proof signature does not match"
        )

    return {
        FORK_PROOF_CHAINS: copy.deepcopy(chains),
        VD_ISSUER: payload[VD_ISSUER],
        KEY_VERSION: payload[KEY_VERSION],
        CP_MOMENT: payload[CP_MOMENT],
        VD_POLICY_DIGEST: recomputed_policy,
        FORK_PROOF_DIGEST: hashlib.sha256(raw).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(payload[FORK_PROOF_REPORT]),
        VERSION: PRUNE_AGGREGATE_FORK_PROOF_VERSION,
    }


def verify_prune_aggregate_fork_proof(proof, prune_policy, keyring, moment):
    """Re-verify a signed prune aggregate fork proof entirely offline.

    Only the proof bytes, the expected shared ``prune_policy``, the
    current ``keyring`` and the verification ``moment`` are consulted
    -- no file is read or written and no argument is modified.
    Verification validates the proof encoding, key sets, version,
    digests, counts, ordering and chain/report references, recomputes
    the forking edges, the crossing chain ids and the conflicted set
    purely from the bound chain materials and demands the bound report
    match exactly, recomputes the prune policy digest, requires the
    signing moment not to be later than the verification moment, and
    verifies the HMAC-SHA256 signature against the key the *current*
    keyring binds to the payload's exact issuer and version, usable at
    the verification moment, so a later revocation or expiry rejects
    the proof.

    On success a fresh independent mapping is returned with the fixed
    keys ``chains``, ``issuer``, ``keyVersion``, ``moment``,
    ``policyDigest``, ``proofDigest`` (the lowercase hex SHA-256 of the
    proof bytes), ``report`` and ``version`` (the integer 1).  A
    non-bytes proof or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    illegal policy, keyring or moment raises :class:`ValueError`; an
    illegal encoding, key set, version, digest, count, ordering,
    reference or report binding raises
    :class:`InvalidAggregateForkProofError` (a :class:`ValueError`
    subclass); and unknown, revoked, not-yet-valid or expired
    credentials or a signature mismatch raise
    :class:`AuthenticationError`.
    """
    if not isinstance(proof, bytes):
        raise TypeError("proof must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    return _verify_pac_fork_proof_core(
        proof, validated_prune_policy, validated_keyring, verify_moment
    )


# -- Offline batch verification of prune aggregate fork proofs ----------------

PAC_FORK_PROOFS_VERSION = 1

_PAC_FORK_PROOF_BATCH_ITEM_KEYS = frozenset((ID, FORK_PROOF_ITEM_PROOF))
_PAC_FORK_PROOFS_VERIFIED = "verified"
_PAC_FORK_PROOFS_INVALID = "invalid-proof"
_PAC_FORK_PROOFS_UNAUTHENTICATED = "unauthenticated"


def _validated_pac_fork_proof_items(items: object) -> list[dict]:
    """Validate the fork-proof batch before any proof is verified.

    The argument must be a non-empty list of dicts each holding exactly
    ``id`` (a non-empty str, unique across the batch) and ``proof``
    (bytes).  Container, element and field type faults raise
    :class:`TypeError`; an empty list, an empty or duplicate id or a
    wrong key set raises :class:`ValueError`.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if not items:
        raise ValueError("items must be a non-empty list")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, item in enumerate(items):
        where = f"item {position}"

    exactly ``rootDigest``, ``predecessorDigest``, ``successors`` (the
    forking successor digests, ascending) and ``ids`` (the ascending
    ids of the chains crossing the edge).  Each item report preserves
    the input order and carries, in this key order, ``error``, ``id``,
    ``result`` and ``status``.  No file is read or written and no input
    is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    reports: list[dict] = []
    results: list[dict | None] = []
    for item in validated_items:
        report = _verify_adc_chain_item(
            item, prune_policy, authorization_policy, site_policy, keyring,
            verify_moment
        )
        reports.append(report)
        results.append(report[VERDICT_ITEM_RESULT])

    # Fork detection within one root group: one predecessor digest
    # pointing at two distinct successor digests, ignoring chains that
    # did not verify.
    groups: dict[str, dict[str, set[str]]] = {}
    for item, result in zip(validated_items, results):
        if result is None:
            continue
        nodes = _pac_chain_edge_nodes(item)
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    fork_edges: dict[tuple[str, str], list[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                fork_edges[(root_digest, upstream)] = sorted(digests)
    edge_ids: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in fork_edges
    }
    if fork_edges:
        for item, report, result in zip(validated_items, reports, results):
            if result is None:
                continue
            nodes = _pac_chain_edge_nodes(item)
            crosses_fork = False
            for upstream in nodes[:-1]:
                edge = (nodes[0], upstream)
                if edge in fork_edges:
                    edge_ids[edge].add(item[ID])
                    crosses_fork = True
            if crosses_fork:
                report[STATUS] = PAC_CHAINS_CONFLICTED
                report[CHECKPOINT_ITEM_ERROR] = _ADC_CHAIN_ITEM_ERROR

    forks = [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: fork_edges[(root_digest, predecessor)],
            _FORK_IDS: sorted(edge_ids[(root_digest, predecessor)]),
        }
        for root_digest, predecessor in sorted(fork_edges)
    ]
    return {
        CHAINS_FORKS: forks,
        ITEMS: reports,
        VERSION: AGGREGATE_DECISION_CHAINS_VERSION,
    }


# -- Stable head anchors for verified, accepted, unforked chains ---------------

def _adc_parse_anchor(raw: object) -> tuple[dict, str]:
    """Validate anchor bytes structurally into ``(payload, signature)``."""
    if not isinstance(raw, bytes):
        raise TypeError("anchor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _adc_anchor_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _adc_anchor_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_adc_anchor_keys
        )
    except json.JSONDecodeError as exc:
        raise _adc_anchor_invalid("is not valid JSON") from exc
    if not isinstance(data, dict):
        raise TypeError("anchor must be a JSON object")
    if set(data.keys()) != _ADC_ANCHOR_TOP_KEYS:
        raise _adc_anchor_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("anchor signature must be a str")
    if not _prune_is_digest(signature):
        raise _adc_anchor_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("anchor payload must be an object")
    if set(payload.keys()) != _ADC_ANCHOR_PAYLOAD_KEYS:
        raise _adc_anchor_invalid(
            "payload must contain exactly the keys 'rootDigest', "
            "'headDigest', 'height', 'policyDigest', 'policyVersion', "
            "'moment', 'issuer', 'keyVersion' and 'version'"
        )
    for key in (_ADC_ROOT_DIGEST, FAC_HEAD_DIGEST, _ADC_POLICY_DIGEST):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _adc_anchor_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[_ADC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 0:
        raise _adc_anchor_invalid("payload height must be non-negative")
    policy_version = payload[_ADC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _adc_anchor_invalid("payload policyVersion must be positive")
    anchor_moment = payload[CP_MOMENT]
    if isinstance(anchor_moment, bool) or not isinstance(anchor_moment, int):
        raise TypeError("payload moment must be an int")
    if anchor_moment < 0:
        raise _adc_anchor_invalid("payload moment must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _adc_anchor_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _adc_anchor_invalid("payload keyVersion must be positive")
    anchor_version = payload[VERSION]
    if isinstance(anchor_version, bool) or not isinstance(
        anchor_version, int
    ):
        raise TypeError("payload version must be an int")
    if anchor_version != AGGREGATE_DECISION_CHAIN_VERSION:
        raise _adc_anchor_invalid("payload version must be the integer 1")
    if _prune_compact(data) != raw:
        raise _adc_anchor_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def seal_aggregate_decision_head(
    items, target, prune_policy, authorization_policy, site_policy, keyring,
    moment, issuer, version,
):
    """Seal a stable anchor over one target head within the batch.

    The batch is first run through the exact
    :func:`verify_aggregate_decision_chains` rules.  An anchor is sealed
    only for the ``target`` chain when it is ``verified`` -- never
    conflicted by a fork in this batch, invalid or unauthenticated --
    and its head is ``accepted``; otherwise sealing raises
    :class:`ValueError`.  Other chains' failures never stop the
    target's anchor, though a fork it shares still reclassifies it.  The
    anchor binds that chain's root digest, head digest and height
    together with the head decision policy digest, the head policy
    version and the sealing moment, and is signed with HMAC-SHA256 under
    the exact ``issuer``/``version`` key usable at ``moment``.

    Returns canonical compact UTF-8 JSON with exactly ``payload`` and
    ``signature``.  A parameter or public field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    empty value, an unknown or duplicate target id, an illegal version
    or a wrong policy count raises :class:`ValueError`; a chain fault
    raises the underlying
    :class:`InvalidAggregateChainForkDecisionAggregateError` or
    :class:`InvalidAggregateDecisionChainError`; a signing credential
    fault raises :class:`AuthenticationError`.  No file is read or
    written and no input is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    seal_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_aggregate_decision_chains(
        items, prune_policy, authorization_policy, site_policy, keyring,
        seal_moment
    )
    target_report = report[ITEMS][target_index]
    target_status = target_report[STATUS]
    if target_status == PAC_CHAINS_INVALID_ROOT:
        raise InvalidAggregateChainForkDecisionAggregateError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_INVALID_CHAIN:
        # The report message already carries the chain-error prefix.
        raise InvalidAggregateDecisionChainError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_UNAUTHENTICATED:
        raise AuthenticationError(target_report[CHECKPOINT_ITEM_ERROR])
    if target_status != PAC_CHAINS_VERIFIED:
        raise ValueError(
            "an anchor seals only a verified target with no fork"
        )
    result = target_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise ValueError("an anchor seals only an accepted head")
    target_item = validated_items[target_index]
    head_packet = (
        target_item[PAC_BATCH_SUCCESSORS][-1]
        if target_item[PAC_BATCH_SUCCESSORS] else target_item[PAC_BATCH_ROOT]
    )
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    if result[FAC_HEAD_DIGEST] != hashlib.sha256(head_packet).hexdigest():
        raise ValueError("the sealed head digest does not match its packet")
    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, seal_moment
    )
    payload = {
        _ADC_ROOT_DIGEST: result[_ADC_ROOT_DIGEST],
        FAC_HEAD_DIGEST: result[FAC_HEAD_DIGEST],
        _ADC_HEIGHT: result[_ADC_HEIGHT],
        _ADC_POLICY_DIGEST: _pac_policy_digest(head_policy),
        _ADC_POLICY_VERSION: result[FAC_POLICY_VERSION],
        CP_MOMENT: seal_moment,
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        VERSION: AGGREGATE_DECISION_CHAIN_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def verify_aggregate_decision_head(
    anchor, items, target, prune_policy, authorization_policy, site_policy,
    keyring, moment,
):
    """Re-verify a sealed aggregate decision anchor entirely offline.

    The anchor is checked structurally and its HMAC verified against the
    current keyring key bound to its exact issuer and version, usable at
    the verification ``moment``; its sealing moment must not be later
    than the verification moment.  The original batch (with ``target``
    naming the anchored chain) is then re-run through
    :func:`verify_aggregate_decision_chains`; the target must again
    verify with no fork and an accepted head, and its root digest, head
    digest, height, policy digest, policy version and sealing moment
    must still match.

    Returns a fresh mapping with fixed keys ``rootDigest``,
    ``headDigest``, ``height``, ``policyDigest``, ``policyVersion`` and
    ``anchorDigest`` (the SHA-256 of the anchor bytes).  A non-bytes or
    wrong-type argument raises :class:`TypeError`; an empty value, a
    duplicate or unknown target id, an illegal version or a wrong policy
    count raises :class:`ValueError`; a malformed root raises
    :class:`InvalidAggregateChainForkDecisionAggregateError`; a bad
    anchor, successor or chain binding raises
    :class:`InvalidAggregateDecisionAnchorError` or
    :class:`InvalidAggregateDecisionChainError`; a signature or
    credential fault raises :class:`AuthenticationError`.  No file is
    read or written and no input is modified.
    """
    if not isinstance(anchor, bytes):
        raise TypeError("anchor must be bytes")
    payload, signature = _adc_parse_anchor(anchor)
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(authorization_policy)
    _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "aggregate decision anchor signature does not match"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _adc_anchor_invalid(
            "the anchor sealing moment is later than the verification moment"
        )

    report = verify_aggregate_decision_chains(
        items, prune_policy, authorization_policy, site_policy, keyring,
        verify_moment
    )
    target_report = report[ITEMS][target_index]
    target_status = target_report[STATUS]
    if target_status == PAC_CHAINS_INVALID_ROOT:
        raise InvalidAggregateChainForkDecisionAggregateError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_INVALID_CHAIN:
        # The report message already carries the chain-error prefix.
        raise InvalidAggregateDecisionChainError(
            target_report[CHECKPOINT_ITEM_ERROR]
        )
    if target_status == PAC_CHAINS_UNAUTHENTICATED:
        raise AuthenticationError(target_report[CHECKPOINT_ITEM_ERROR])
    if target_status != PAC_CHAINS_VERIFIED:
        raise _adc_anchor_invalid(
            "the anchored target no longer verifies without a fork"
        )
    result = target_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise _adc_anchor_invalid("the anchored head is no longer accepted")
    target_item = validated_items[target_index]
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    head_policy_digest = _pac_policy_digest(head_policy)
    if result[_ADC_ROOT_DIGEST] != payload[_ADC_ROOT_DIGEST]:
        raise _adc_anchor_invalid("root digest does not match the anchor")
    if result[FAC_HEAD_DIGEST] != payload[FAC_HEAD_DIGEST]:
        raise _adc_anchor_invalid("head digest does not match the anchor")
    if result[_ADC_HEIGHT] != payload[_ADC_HEIGHT]:
        raise _adc_anchor_invalid("height does not match the anchor")
    if result[FAC_POLICY_VERSION] != payload[_ADC_POLICY_VERSION]:
        raise _adc_anchor_invalid(
            "policy version does not match the anchor"
        )
    if head_policy_digest != payload[_ADC_POLICY_DIGEST]:
        raise _adc_anchor_invalid("policy digest does not match the anchor")
    return {
        _ADC_ROOT_DIGEST: payload[_ADC_ROOT_DIGEST],
        FAC_HEAD_DIGEST: payload[FAC_HEAD_DIGEST],
        _ADC_HEIGHT: payload[_ADC_HEIGHT],
        _ADC_POLICY_DIGEST: head_policy_digest,
        _ADC_POLICY_VERSION: payload[_ADC_POLICY_VERSION],
        _ADC_ANCHOR_DIGEST: hashlib.sha256(anchor).hexdigest(),
    }


# ===========================================================================
# Signed fork proofs, multi-site threshold adjudication and offline decision
# verification over aggregate decision chain batches
# ===========================================================================
#
# This layer packages the
# :func:`verify_aggregate_decision_chains` batch the way the aggregate
# chain fork proof layer packages
# :func:`verify_decision_aggregate_chains`, but three *invariant*
# policies share the whole batch and are digested inside every signed
# proof -- the original prune policy, the site authorization policy and
# the fork-proof signer site policy; the versioned decision site policy
# history is carried per stage inside the chain materials.  Unlike the
# earlier fork proof layers, a proof may attest a fork-free batch: the
# fork edge collection is then bound empty and an authenticated proof
# still declares that empty set.  Adjudication additionally takes the
# signer site policy that authorizes the exact proof signer identity
# and key version, and the decision binds four policy digests.

AGGREGATE_DECISION_CHAIN_FORK_PROOF_VERSION = 1
AGGREGATE_DECISION_CHAIN_FORK_DECISION_VERSION = 1

_ADCF_PROOFS_VERSION = 1
_ADCF_PROOFS_VERIFIED = _CF_PROOFS_VERIFIED
_ADCF_PROOFS_INVALID = _CF_PROOFS_INVALID
_ADCF_PROOFS_UNAUTHENTICATED = _CF_PROOFS_UNAUTHENTICATED

_ADCF_PROOF_SITE_POLICY = CF_PROOF_SITE_POLICY
_ADCF_SITE_POLICY_DIGEST = PAFD_SITE_POLICY_DIGEST
_ADCF_SIGNER_SITE_POLICY_DIGEST = "signerSitePolicyDigest"

_ADCF_PROOF_PAYLOAD_KEYS = frozenset((
    FORK_PROOF_CHAINS,
    VD_ISSUER,
    KEY_VERSION,
    CP_MOMENT,
    CF_PROOF_PRUNE_POLICY,
    FORK_PROOF_REPORT,
    _ACF_PROOF_AUTHORIZATION_POLICY,
    _ADCF_PROOF_SITE_POLICY,
    VERSION,
))

_ADCF_DECISION_PAYLOAD_KEYS = frozenset((
    PAFD_COMMON,
    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    PAFD_PRUNE_POLICY_DIGEST,
    PAFD_PROOFS,
    _ACF_DECISION_AUTHORIZATION_POLICY_DIGEST,
    _ADCF_SITE_POLICY_DIGEST,
    _ADCF_SIGNER_SITE_POLICY_DIGEST,
    STATUS,
    VERSION,
))


class InvalidAggregateDecisionChainForkProofError(ValueError):
    """An aggregate decision chain fork proof breaks its contract."""


class InvalidAggregateDecisionChainForkDecisionError(ValueError):
    """An aggregate decision chain fork decision breaks its contract."""


def _adcf_proof_invalid(
    message: str,
) -> InvalidAggregateDecisionChainForkProofError:
    return InvalidAggregateDecisionChainForkProofError(
        f"invalid aggregate decision chain fork proof: {message}"
    )


def _adcf_decision_invalid(
    message: str,
) -> InvalidAggregateDecisionChainForkDecisionError:
    return InvalidAggregateDecisionChainForkDecisionError(
        f"invalid aggregate decision chain fork decision: {message}"
    )


def _reject_duplicate_adcf_proof_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate proof keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _adcf_proof_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _reject_duplicate_adcf_decision_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate decision keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _adcf_decision_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _parse_adcf_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate aggregate decision chain fork proof bytes structurally.

    Returns ``(payload, signature, chains)``.  A non-bytes argument or a
    public field of the wrong type raises :class:`TypeError` (a
    :class:`bool` never poses as an int); every encoding, key-set,
    version, digest, count, ordering, reference or report-binding fault
    raises :class:`InvalidAggregateDecisionChainForkProofError`.  The
    three policy bindings, the moment and the signature are checked by
    the proof verifier.  Unlike the earlier fork proofs, the bound
    report may carry no fork at all -- its fork collection is then
    empty.
    """
    if not isinstance(raw, bytes):
        raise TypeError("proof must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _adcf_proof_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _adcf_proof_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_adcf_proof_keys
        )
    except json.JSONDecodeError as exc:
        raise _adcf_proof_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("proof must be a JSON object")
    if set(data.keys()) != _CF_PROOF_TOP_KEYS:
        raise _adcf_proof_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("proof signature must be a str")
    if not _prune_is_digest(signature):
        raise _adcf_proof_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("proof payload must be an object")
    if set(payload.keys()) != _ADCF_PROOF_PAYLOAD_KEYS:
        raise _adcf_proof_invalid(
            "payload must contain exactly the keys 'chains', 'issuer', "
            "'keyVersion', 'moment', 'prunePolicy', 'report', "
            "'authorizationPolicy', 'sitePolicy' and 'version'"
        )
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _adcf_proof_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _adcf_proof_invalid("payload keyVersion must be positive")
    moment = payload[CP_MOMENT]
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("payload moment must be an int")
    if moment < 0:
        raise _adcf_proof_invalid("payload moment must be non-negative")
    for field in (
        CF_PROOF_PRUNE_POLICY,
        _ACF_PROOF_AUTHORIZATION_POLICY,
        _ADCF_PROOF_SITE_POLICY,
    ):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _adcf_proof_invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("payload version must be an int")
    if version != AGGREGATE_DECISION_CHAIN_FORK_PROOF_VERSION:
        raise _adcf_proof_invalid("payload version must be the integer 1")
    chains = _validated_pac_fork_chains(
        payload[FORK_PROOF_CHAINS], invalid=_adcf_proof_invalid
    )
    _validated_pac_fork_report(
        payload[FORK_PROOF_REPORT], chains,
        conflicted_error=_ADC_CHAIN_ITEM_ERROR,
        invalid=_adcf_proof_invalid,
        report_version=AGGREGATE_DECISION_CHAINS_VERSION,
        require_fork=False,
    )

    if _prune_compact(data) != raw:
        raise _adcf_proof_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature, chains


def sign_aggregate_decision_chain_fork_proof(items, prune_policy,
                                            authorization_policy, site_policy,
                                            keyring, moment, issuer, version):
    """Sign the fork summary of an aggregate decision chain batch.

    ``items`` is the same non-empty list of ``{"id", "root",
    "successors", "policies"}`` dicts
    :func:`verify_aggregate_decision_chains` takes; ``prune_policy`` is
    the shared invariant original ``{"batch","sites","threshold"}``
    pruning policy, ``authorization_policy`` the shared invariant site
    authorization policy and ``site_policy`` the shared invariant
    fork-proof signer site policy; ``keyring`` follows the existing
    rules, ``moment`` is the signing time and ``issuer``/``version``
    name the signing credentials.  The batch first runs through the
    exact :func:`verify_aggregate_decision_chains` rules; unlike the
    earlier fork proof layers, a proof is issued even when the batch
    reports no fork -- the fork edge collection is then bound empty,
    and invalid or unauthenticated chains never contribute an edge.
    No file is read or written and no argument is modified.

    The proof is one canonical compact UTF-8 JSON object -- every
    object key recursively sorted, non-ASCII preserved, no trailing
    newline or any other trailing byte -- carrying exactly ``payload``
    and ``signature``.  The payload binds exactly ``chains`` (every
    input chain in original input order: ``id``, the ``root`` digest,
    every ``successors`` digest and the canonical digest of every
    versioned decision site policy in the complete ``policies``
    history), ``issuer``, ``keyVersion``, ``moment``, ``prunePolicy``
    (the lowercase hex SHA-256 of the canonical compact prune policy
    encoding), ``report`` (the complete chain-batch report, including
    its per-chain conclusions and the possibly empty fork collection),
    ``authorizationPolicy`` (the SHA-256 of the canonical compact site
    authorization policy), ``sitePolicy`` (the SHA-256 of the canonical
    compact fork-proof signer site policy) and ``version`` (the
    integer 1).  ``signature`` is the lowercase hex HMAC-SHA256 of the
    canonical compact payload bytes under the key the keyring binds to
    the exact issuer and version, with no fallback.

    A parameter or public field type fault raises :class:`TypeError` (a
    :class:`bool` never poses as an int); an empty list, an empty or
    duplicate id, a wrong policy count, an empty issuer, a non-positive
    version, a negative moment or an illegal shared policy raises
    :class:`ValueError`; and unknown, revoked, not-yet-valid or expired
    credentials raise :class:`AuthenticationError`.
    """
    validated_items = _validated_fac_chain_batch(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    sign_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_aggregate_decision_chains(
        validated_items, prune_policy, authorization_policy, site_policy,
        keyring, sign_moment,
    )
    entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, sign_moment
    )
    payload = {
        FORK_PROOF_CHAINS: _pac_chain_materials(validated_items),
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        CP_MOMENT: sign_moment,
        CF_PROOF_PRUNE_POLICY: hashlib.sha256(
            _verdict_policy_bytes(validated_prune_policy)
        ).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(report),
        _ACF_PROOF_AUTHORIZATION_POLICY: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_authorization_policy)
        ).hexdigest(),
        _ADCF_PROOF_SITE_POLICY: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_site_policy)
        ).hexdigest(),
        VERSION: AGGREGATE_DECISION_CHAIN_FORK_PROOF_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _verify_adcf_fork_proof_core(
    raw: bytes,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one aggregate decision chain fork proof in isolation.

    Shared core of the batch verifier; the caller owns the
    argument-type and shared-material validation.  The returned dict is
    freshly built solely from authenticated proof material.
    """
    payload, signature, chains = _parse_adcf_fork_proof(raw)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[CF_PROOF_PRUNE_POLICY] != expected_prune_digest:
        raise _adcf_proof_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_authorization_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if payload[_ACF_PROOF_AUTHORIZATION_POLICY] != expected_authorization_digest:
        raise _adcf_proof_invalid(
            "authorization policy digest does not match the authorization "
            "policy"
        )
    expected_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[_ADCF_PROOF_SITE_POLICY] != expected_site_digest:
        raise _adcf_proof_invalid(
            "site policy digest does not match the signer site policy"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _adcf_proof_invalid(
            "moment must not be later than the verification moment"
        )

    key_entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "aggregate decision chain fork proof signature does not match"
        )

    return {
        FORK_PROOF_CHAINS: copy.deepcopy(chains),
        VD_ISSUER: payload[VD_ISSUER],
        KEY_VERSION: payload[KEY_VERSION],
        CP_MOMENT: payload[CP_MOMENT],
        PAFD_PRUNE_POLICY_DIGEST: expected_prune_digest,
        _ACF_AUTHORIZATION_POLICY_DIGEST: expected_authorization_digest,
        _ADCF_SITE_POLICY_DIGEST: expected_site_digest,
        FORK_PROOF_DIGEST: hashlib.sha256(raw).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(payload[FORK_PROOF_REPORT]),
        VERSION: AGGREGATE_DECISION_CHAIN_FORK_PROOF_VERSION,
    }


# -- Offline batch verification of aggregate decision chain fork proofs --------

def _adcf_proofs_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One aggregate decision chain fork proof report, fixed key order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_adcf_fork_proof_item(
    item: dict,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify one aggregate decision chain fork proof in isolation.

    Unknown, revoked, not-yet-valid or expired credentials and a wrong
    signature make the item ``unauthenticated``; every encoding,
    key-set, version, digest, ordering, reference or report-binding
    fault makes it ``invalid-proof``; a passing proof is ``verified``.
    """
    item_id = item[ID]
    try:
        result = _verify_adcf_fork_proof_core(
            item[FORK_PROOF_ITEM_PROOF],
            validated_prune_policy,
            validated_authorization_policy,
            validated_site_policy,
            validated_keyring,
            moment,
        )
    except AuthenticationError as exc:
        return _adcf_proofs_item_report(
            item_id, _ADCF_PROOFS_UNAUTHENTICATED, str(exc), None
        )
    except (InvalidAggregateDecisionChainForkProofError, TypeError) as exc:
        # A TypeError here can only come from a wrong JSON field type
        # *inside* the proof bytes; the public argument types were all
        # validated before the batch ran.
        return _adcf_proofs_item_report(
            item_id, _ADCF_PROOFS_INVALID, str(exc), None
        )
    return _adcf_proofs_item_report(
        item_id, _ADCF_PROOFS_VERIFIED, None, result
    )


def verify_aggregate_decision_chain_fork_proofs(
    items, prune_policy, authorization_policy, site_policy, keyring, moment,
):
    """Verify a whole batch of aggregate decision chain fork proofs offline.

    ``items`` is a non-empty list; each item is a dict with exactly the
    keys ``id`` (a non-empty str, unique across the batch) and ``proof``
    (the bytes :func:`sign_aggregate_decision_chain_fork_proof`
    produced).  The whole batch structure and the shared prune policy,
    site authorization policy, fork-proof signer site policy, keyring
    and moment are validated in full before any proof is verified:
    container, element or field type faults raise :class:`TypeError` (a
    :class:`bool` never poses as an int) and an empty list, an empty or
    duplicate id or a wrong item key set raises :class:`ValueError`
    (the shared materials keep their single-entry classification).
    Only these batch-level faults raise.

    Each proof is then verified independently, in strict input order:
    one proof's failure never stops a later proof or alters an earlier
    report, and a failed item always keeps a null result and a definite
    non-empty error.  Unknown, revoked, not-yet-valid or expired
    credentials or a wrong signature make the item
    ``unauthenticated``; an illegal encoding, key set, version, digest,
    count, ordering, reference or report binding makes it
    ``invalid-proof``; a passing proof is ``verified`` and its result
    carries ``proofDigest`` (the SHA-256 of the proof bytes).

    The top-level result is a fresh dict with the fixed keys ``items``
    and ``version`` (the integer 1); each item report carries, in this
    key order, ``error`` (null exactly when verified), ``id``,
    ``result`` (a fresh independent copy of the single-proof result
    when verified, otherwise null -- the identity of an unauthenticated
    payload never enters a result) and ``status``.  Repeated calls
    return equal but mutually independent results.  No file is read or
    written and no input is modified.
    """
    validated_items = _validated_pac_fork_proof_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")
    return {
        ITEMS: [
            _verify_adcf_fork_proof_item(
                item, validated_prune_policy, validated_authorization_policy,
                validated_site_policy, validated_keyring, verify_moment,
            )
            for item in validated_items
        ],
        VERSION: _ADCF_PROOFS_VERSION,
    }


# -- Multi-site threshold adjudication over the fork proofs --------------------

def _adjudicate_adcf_one(
    item: dict,
    prune_policy_digest: str,
    authorization_policy_digest: str,
    site_policy_digest: str,
    signer_site_policy: dict,
    keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify, authorize and authenticate one aggregate decision chain proof.

    The proof is first checked through the exact aggregate decision
    chain fork proof structural rules, then the signing site and key
    version are authorized exactly against the separate signer site
    policy with no fallback, and finally the HMAC is checked against the
    current keyring.  Any failure rejects just this row with one fixed
    reason and never affects the other items.
    """
    item_id = item[ID]
    raw_proof = item[FORK_PROOF_ITEM_PROOF]
    proof_digest = hashlib.sha256(raw_proof).hexdigest()

    def structural_invalid() -> dict:
        return _cf_row(
            item_id, proof_digest, None, None, None,
            _PAFD_CONCLUSION_INVALID, _PAFD_REASON_INVALID_PROOF,

        )

    try:
        payload, signature, _chains = _parse_adcf_fork_proof(raw_proof)
    except (TypeError, ValueError):
        return structural_invalid()

    site = payload[VD_ISSUER]
    key_version = payload[KEY_VERSION]
    try:
        edges = _pac_fork_proof_edges(payload)
    except (TypeError, ValueError):
        return structural_invalid()

    def reject(reason: str) -> dict:
        return _cf_row(
            item_id, proof_digest, site, key_version, edges,
            _PAFD_CONCLUSION_INVALID, reason,
        )

    # All three shared policy digests must match and the proof must not
    # be dated after the adjudication moment; a mismatch makes the
    # claimed identity untrustworthy, so the row carries none.
    # Authorization itself is governed by the separate signer site
    # policy.
    if payload[CF_PROOF_PRUNE_POLICY] != prune_policy_digest:
        return structural_invalid()
    if payload[_ACF_PROOF_AUTHORIZATION_POLICY] != authorization_policy_digest:
        return structural_invalid()
    if payload[_ADCF_PROOF_SITE_POLICY] != site_policy_digest:
        return structural_invalid()
    if payload[CP_MOMENT] > moment:
        return structural_invalid()

    allowed_versions = signer_site_policy[ADJ_SITES].get(site)
    if allowed_versions is None:
        return reject(REASON_UNAUTHORIZED_SITE)
    if key_version not in allowed_versions:
        return reject(REASON_UNAUTHORIZED_VERSION)

    key_entry = None
    for candidate in keyring.get(site, ()):
        if candidate[VERSION] == key_version:
            key_entry = candidate
            break
    if key_entry is None:
        return reject(REASON_CREDENTIAL_UNAVAILABLE)
    if key_entry[REVOKED]:
        return reject(REASON_REVOKED)
    if moment < key_entry[NOT_BEFORE]:
        return reject(REASON_NOT_YET_VALID)
    if moment > key_entry[NOT_AFTER]:
        return reject(REASON_EXPIRED)

    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        return reject(REASON_BAD_SIGNATURE)

    return _cf_row(
        item_id, proof_digest, site, key_version, edges,
        _PAFD_CONCLUSION_VALID, None,
    )


def adjudicate_aggregate_decision_chain_forks(
    items, prune_policy, authorization_policy, site_policy,
    signer_site_policy, keyring, moment, issuer, version,
):
    """Adjudicate multi-site aggregate decision chain fork proofs offline.

    ``items`` is a non-empty list; each item contains exactly a unique
    non-empty ``id`` and ``proof`` bytes produced by
    :func:`sign_aggregate_decision_chain_fork_proof`.  ``prune_policy``
    is the shared invariant original ``{"batch","sites","threshold"}``
    pruning policy the proofs were issued against,
    ``authorization_policy`` the invariant site authorization policy
    their payloads digest and ``site_policy`` the invariant fork-proof
    signer site policy their payloads digest; ``signer_site_policy``
    additionally carries exactly ``sites`` (a non-empty map of each
    authorized non-empty signing site to its non-empty set of allowed
    positive key versions) and ``threshold`` (a positive integer no
    greater than the site count).  ``keyring`` follows the existing
    rules, ``moment`` is the non-negative adjudication moment and
    ``issuer``/``version`` name the adjudicator credentials.  No file
    is read or written and no input is modified.

    Every proof is first independently re-verified through the
    aggregate decision chain fork proof rules (a structurally illegal,
    foreign-policy or future-dated proof is ``invalid-proof`` carrying
    no identity), then authorized precisely by the exact payload
    identity and key version against the signer site policy with no
    fallback (``unauthorized-site``, ``unauthorized-version``), then
    authenticated against the current keyring
    (``credential-unavailable``, ``revoked``, ``not-yet-valid``,
    ``expired``, ``bad-signature``); one item's rejection never blocks
    a later item.  The authenticated declaration is the proof's
    complete fork edge set -- every edge of root digest, forking
    predecessor digest and the ascending set of legal successor
    digests -- which is the empty set for a proof that attests a
    fork-free batch.  For one site, proofs whose complete declaration
    is identical count once and every extra proof is ``duplicate``,
    while two distinct declarations from one site are a
    ``contradiction``.  Distinct sites must agree exactly; any
    same-site contradiction or cross-site difference is
    ``conflicted`` with a null common declaration and can never be
    outvoted by a majority.  A unique declaration backed by at least
    the threshold of distinct sites is ``accepted``; the same unique
    declaration short of the threshold is ``insufficient`` yet still
    binds that declaration (an empty list for a fork-free one); with
    no valid vote at all the common declaration is null.

    The packet is one canonical compact UTF-8 JSON object with
    recursively sorted keys, non-ASCII preserved and no trailing byte,
    carrying exactly ``payload`` and ``signature``; the payload binds
    exactly the four policy digests -- ``prunePolicyDigest``,
    ``authorizationPolicyDigest``, ``sitePolicyDigest`` (the
    fork-proof signer site policy already digested inside every proof)
    and ``signerSitePolicyDigest`` -- together with ``common`` (the
    stable-sorted common fork edge set, possibly empty, or null),
    ``issuer``, ``items`` (the rows stably sorted by site then id, each
    carrying ``conclusion``, the authenticated ``edges`` or null,
    ``id``, ``issuer``, ``keyVersion``, the proof ``digest`` and
    ``reason``), ``keyVersion``, ``proofs`` (the per-row proof SHA-256
    digests bound term by term to the canonical site/id-sorted rows, so
    reordering the summaries and re-signing is rejected), ``status``
    and ``version`` (the integer 1).  The signature is the lowercase
    hex HMAC-SHA256 of the canonical payload bytes under the exact
    adjudicator issuer/version key.  The result bytes are independent
    of the input item order.

    A parameter, container or public-field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    empty list, an empty or duplicate id, or an illegal policy,
    threshold, moment, issuer or version raises :class:`ValueError`;
    unknown, revoked, not-yet-valid or expired adjudicator credentials
    raise :class:`AuthenticationError`.
    """
    validated_items = _validated_pac_fork_proof_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_signer_site_policy = _validated_prune_batch_site_policy(
        signer_site_policy
    )
    validated_keyring = _validated_keyring(keyring)
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("moment must be an int")
    if moment < 0:
        raise ValueError("moment must be non-negative")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    authorization_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()

    rows = [
        _adjudicate_adcf_one(
            item, prune_policy_digest, authorization_policy_digest,
            site_policy_digest, validated_signer_site_policy,
            validated_keyring, moment,
        )
        for item in validated_items
    ]

    contradicted, votes = _tally_pac_fork_rows(rows)

    declarations = set(votes.values())
    if contradicted or len(declarations) > 1:
        status = _CF_STATUS_CONFLICTED
        common = None
    elif len(declarations) == 1:
        common = _sorted_pac_fork_edge_objects(next(iter(declarations)))
        if len(votes) >= validated_signer_site_policy[ADJ_THRESHOLD]:
            status = _CF_STATUS_ACCEPTED
        else:
            status = _CF_STATUS_INSUFFICIENT
    else:
        status = _CF_STATUS_INSUFFICIENT
        common = None

    rows.sort(
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        )
    )
    # The proof summary vector corresponds term by term to the canonical
    # (sorted) rows, so a reordering of the summaries that is then
    # re-signed is detectable offline without seeing any proof even
    # though the digest multiset is unchanged.
    proof_digests = [row[_CF_PROOF_DIGEST] for row in rows]

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, moment
    )
    payload = {
        _CF_DECISION_COMMON: common,
        VD_ISSUER: issuer,
        ITEMS: [copy.deepcopy(row) for row in rows],
        KEY_VERSION: version,
        PAFD_PRUNE_POLICY_DIGEST: prune_policy_digest,
        _CF_DECISION_PROOFS: proof_digests,
        _ACF_DECISION_AUTHORIZATION_POLICY_DIGEST: authorization_policy_digest,
        _ADCF_SITE_POLICY_DIGEST: site_policy_digest,
        _ADCF_SIGNER_SITE_POLICY_DIGEST: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_signer_site_policy)
        ).hexdigest(),
        STATUS: status,
        VERSION: AGGREGATE_DECISION_CHAIN_FORK_DECISION_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _parse_adcf_decision(raw: object) -> tuple[dict, str]:
    """Validate aggregate decision chain fork decision bytes structurally.

    A non-bytes argument or a field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest or value-format fault raises
    :class:`InvalidAggregateDecisionChainForkDecisionError`.  The four
    policy bindings, the tally and the signature are checked by the
    decision verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("decision must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _adcf_decision_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _adcf_decision_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_adcf_decision_keys
        )
    except json.JSONDecodeError as exc:
        raise _adcf_decision_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("decision must be a JSON object")
    if set(data.keys()) != _PAFD_DECISION_TOP_KEYS:
        raise _adcf_decision_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("decision signature must be a str")
    if not _prune_is_digest(signature):
        raise _adcf_decision_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("decision payload must be an object")
    if set(payload.keys()) != _ADCF_DECISION_PAYLOAD_KEYS:
        raise _adcf_decision_invalid(
            "payload must contain exactly the keys 'common', 'issuer', "
            "'items', 'keyVersion', 'prunePolicyDigest', 'proofs', "
            "'authorizationPolicyDigest', 'sitePolicyDigest', "
            "'signerSitePolicyDigest', 'status' and 'version'"
        )

    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _adcf_decision_invalid(
            "payload issuer must be a non-empty str"
        )
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _adcf_decision_invalid("payload keyVersion must be positive")
    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PAFD_STATUSES:
        raise _adcf_decision_invalid("payload status is not a known status")
    for field in (
        PAFD_PRUNE_POLICY_DIGEST,
        _ACF_DECISION_AUTHORIZATION_POLICY_DIGEST,
        _ADCF_SITE_POLICY_DIGEST,
        _ADCF_SIGNER_SITE_POLICY_DIGEST,
    ):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _adcf_decision_invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )

    proofs = payload[PAFD_PROOFS]
    if not isinstance(proofs, list):
        raise TypeError("payload proofs must be a list")
    if not proofs:
        raise _adcf_decision_invalid("payload proofs must be non-empty")
    for position, digest in enumerate(proofs):
        if not isinstance(digest, str):
            raise TypeError(f"payload proof {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _adcf_decision_invalid(
                f"payload proof {position} digest must be 64 lowercase hex "
                "characters"
            )

    raw_rows = payload[ITEMS]
    if not isinstance(raw_rows, list):
        raise TypeError("payload items must be a list")
    if not raw_rows:
        raise _adcf_decision_invalid("payload items must be non-empty")
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        where = f"payload item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{where} must be an object")
        if set(row.keys()) != _PAFD_ROW_KEYS:
            raise _adcf_decision_invalid(
                f"{where} must contain exactly the keys 'conclusion', "
                "'edges', 'id', 'keyVersion', 'digest', 'reason' and "
                "'site'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{where} id must be a str")
        if row_id == "":
            raise _adcf_decision_invalid(f"{where} id must be non-empty")
        if row_id in seen_ids:
            raise _adcf_decision_invalid(f"{where} repeats an id")
        seen_ids.add(row_id)
        digest = row[_CF_PROOF_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _adcf_decision_invalid(
                f"{where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None:
            if not isinstance(site, str):
                raise TypeError(f"{where} site must be a str or null")
            if site == "":
                raise _adcf_decision_invalid(f"{where} site must be non-empty")
        row_key_version = row[KEY_VERSION]
        if isinstance(row_key_version, bool) or not isinstance(
            row_key_version, int
        ):
            if row_key_version is not None:
                raise TypeError(f"{where} keyVersion must be an int or null")
        elif row_key_version <= 0:
            raise _adcf_decision_invalid(
                f"{where} keyVersion must be positive"
            )
        if (site is None) != (row_key_version is None):
            raise _adcf_decision_invalid(
                f"{where} site and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{where} conclusion must be a str")
        if conclusion not in _PAFD_CONCLUSIONS:
            raise _adcf_decision_invalid(f"{where} conclusion is not known")
        reason = row[ADJ_REASON]
        if conclusion == _PAFD_CONCLUSION_VALID:
            if reason is not None:
                raise _adcf_decision_invalid(
                    f"{where} reason must be null for a valid item"
                )
        else:
            if not isinstance(reason, str):
                raise TypeError(f"{where} reason must be a str")
            if reason not in _PAFD_REASONS:
                raise _adcf_decision_invalid(f"{where} reason is not known")
        if conclusion == _PAFD_CONCLUSION_INVALID:
            if reason not in _PAFD_INVALID_REASONS:
                raise _adcf_decision_invalid(
                    f"{where} reason does not match an invalid item"
                )
        elif conclusion != _PAFD_CONCLUSION_VALID:
            if reason != conclusion:
                raise _adcf_decision_invalid(
                    f"{where} reason must match its conclusion"
                )

        raw_edges = row[PAFD_EDGES]
        if raw_edges is not None:
            # An authenticated row may legitimately declare the empty
            # fork edge set: a fork-free batch is still a declaration.
            if not isinstance(raw_edges, list):
                raise TypeError(f"{where} edges must be a list or null")
            row_edges = [
                _validated_pafd_edge(value, where, _adcf_decision_invalid)
                for value in raw_edges
            ]
            triples = _pac_fork_edge_triples(row_edges)
            if len(set(triples)) != len(triples):
                raise _adcf_decision_invalid(f"{where} edges must be unique")
            if list(triples) != sorted(triples):
                raise _adcf_decision_invalid(
                    f"{where} edges must be sorted ascending"
                )
        identity_expected = reason != _PAFD_REASON_INVALID_PROOF
        if identity_expected:
            if site is None or raw_edges is None:
                raise _adcf_decision_invalid(
                    f"{where} an authenticated proof must carry its site and "
                    "fork edges"
                )
        else:
            if site is not None or raw_edges is not None:
                raise _adcf_decision_invalid(
                    f"{where} an invalid-proof item must carry no site or "
                    "fork edges"
                )

    common = payload[PAFD_COMMON]
    if common is not None:
        if not isinstance(common, list):
            raise TypeError("payload common must be a list or null")
        common_edges = [
            _validated_pafd_edge(value, "payload common",
                                 _adcf_decision_invalid)
            for value in common
        ]
        common_triples = _pac_fork_edge_triples(common_edges)
        if len(set(common_triples)) != len(common_triples) or list(
            common_triples
        ) != sorted(common_triples):
            raise _adcf_decision_invalid(
                "payload common edges must be unique and sorted ascending"
            )

    decision_version = payload[VERSION]
    if isinstance(decision_version, bool) or not isinstance(
        decision_version, int
    ):
        raise TypeError("payload version must be an int")
    if decision_version != AGGREGATE_DECISION_CHAIN_FORK_DECISION_VERSION:
        raise _adcf_decision_invalid("payload version must be the integer 1")

    if _prune_compact(data) != raw:
        raise _adcf_decision_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def verify_aggregate_decision_chain_fork_decision(
    decision, prune_policy, authorization_policy, site_policy,
    signer_site_policy, keyring, moment,
):
    """Re-verify a signed aggregate decision chain fork decision offline.

    Only the decision bytes, the expected shared ``prune_policy``, the
    invariant site ``authorization_policy``, the invariant fork-proof
    ``site_policy``, the expected ``signer_site_policy``, the current
    ``keyring`` and the verification ``moment`` are consulted -- no file
    is read or written and no argument is modified.  The decision binds
    four policy digests (the prune policy, the site authorization
    policy, the fork-proof signer site policy and the adjudication
    signer site policy).  Verification validates the canonical encoding
    and every key set, recomputes all four policy digests, re-tallies
    the bound per-proof rows purely from the signed payload (the
    term-by-term proof digest bindings over the canonical rows, the
    stable site/id row ordering, the same-site
    duplicate/contradiction markings, the cross-site declaration
    agreement, the signer threshold outcome and the claimed common
    declaration, which is an empty list when every authenticated proof
    attests a fork-free batch), and checks the HMAC-SHA256 against the
    key the current keyring binds to the payload's exact issuer and
    version, usable at the verification moment, so a later revocation
    or expiry rejects the decision with no fallback.

    On success a fresh depth-independent mapping is returned with the
    fixed keys ``common``, ``proofDigest`` (the SHA-256 of the decision
    bytes), ``issuer``, ``items``, ``keyVersion``,
    ``prunePolicyDigest``, ``proofs``, ``authorizationPolicyDigest``,
    ``sitePolicyDigest``, ``signerSitePolicyDigest``, ``status`` and
    ``version`` (the integer 1); repeated calls return equal but
    mutually independent objects and unauthenticated identities and
    boundaries never enter a result.  A non-bytes decision or a wrong
    public field type raises :class:`TypeError` (a :class:`bool` never
    poses as an int); an empty value, a duplicate id, a wrong key set
    or an illegal policy, threshold, moment, identity or version raises
    :class:`ValueError`; an illegal decision structure, ordering, tally
    or binding raises
    :class:`InvalidAggregateDecisionChainForkDecisionError` (a
    :class:`ValueError` subclass); unknown, revoked, not-yet-valid or
    expired credentials or a wrong signature raise
    :class:`AuthenticationError`.
    """
    if not isinstance(decision, bytes):
        raise TypeError("decision must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_signer_site_policy = _validated_prune_batch_site_policy(
        signer_site_policy
    )
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    payload, signature = _parse_adcf_decision(decision)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[PAFD_PRUNE_POLICY_DIGEST] != expected_prune_digest:
        raise _adcf_decision_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_authorization_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if payload[_ACF_DECISION_AUTHORIZATION_POLICY_DIGEST] != \
            expected_authorization_digest:
        raise _adcf_decision_invalid(
            "authorization policy digest does not match the authorization "
            "policy"
        )
    expected_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[_ADCF_SITE_POLICY_DIGEST] != expected_site_digest:
        raise _adcf_decision_invalid(
            "site policy digest does not match the fork-proof signer site "
            "policy"
        )
    expected_signer_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_signer_site_policy)
    ).hexdigest()
    if payload[_ADCF_SIGNER_SITE_POLICY_DIGEST] != expected_signer_digest:
        raise _adcf_decision_invalid(
            "signer site policy digest does not match the signer site policy"
        )

    # The proof digest vector is bound term by term to the canonical
    # (stably sorted) rows, so a reordering of the summaries that is then
    # re-signed is rejected even though the digest multiset is unchanged.
    status = _reconcile_pafd(
        payload, validated_signer_site_policy[ADJ_THRESHOLD],
        invalid=_adcf_decision_invalid, positional_proofs=True,
    )

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "aggregate decision chain fork decision signature does not match"
        )

    return {
        PAFD_COMMON: copy.deepcopy(payload[PAFD_COMMON]),
        FORK_PROOF_DIGEST: hashlib.sha256(decision).hexdigest(),
        VD_ISSUER: payload[VD_ISSUER],
        ITEMS: copy.deepcopy(payload[ITEMS]),
        KEY_VERSION: payload[KEY_VERSION],
        PAFD_PRUNE_POLICY_DIGEST: expected_prune_digest,
        PAFD_PROOFS: list(payload[PAFD_PROOFS]),
        _ACF_AUTHORIZATION_POLICY_DIGEST: expected_authorization_digest,
        _ADCF_SIGNER_SITE_POLICY_DIGEST: expected_signer_digest,
        _ADCF_SITE_POLICY_DIGEST: expected_site_digest,
        STATUS: status,
        VERSION: AGGREGATE_DECISION_CHAIN_FORK_DECISION_VERSION,
    }


# ===========================================================================
# Batch verification and cross-site aggregation of aggregate decision chain
# fork decisions
# ===========================================================================
#
# This layer mirrors the aggregate chain fork decision aggregate
# (``acfda``) layer one stack higher: its source packets are
# :func:`adjudicate_aggregate_decision_chain_forks` decisions, so each
# one binds four policy digests (the prune policy, the site
# authorization policy, the fork-proof signer site policy and the
# adjudication signer site policy), the per-proof summaries stay bound
# term by term to the canonical site/id-sorted rows, and -- unlike the
# earlier aggregate layers -- a fork-free decision legally carries the
# empty common fork edge set.  The cross-site aggregate adds the fifth
# (decision site) policy digest; its own error hierarchy is distinct.

AGGREGATE_DECISION_CHAIN_FORK_DECISIONS_VERSION = 1
AGGREGATE_DECISION_CHAIN_FORK_DECISION_AGGREGATE_VERSION = 1

_ADCFD_VERIFIED = _VERIFY_VERIFIED
_ADCFD_INVALID = "invalid-decision"
_ADCFD_UNAUTHENTICATED = VERIFY_UNAUTHENTICATED

_ADCFDA_PACKET = _CFD_DECISION
_ADCFDA_INPUTS = PFDA_INPUTS
_ADCFDA_DECLARATION = PFDA_DECLARATION
_ADCFDA_PRUNE_POLICY_DIGEST = PFDA_PRUNE_POLICY_DIGEST
_ADCFDA_AUTHORIZATION_POLICY_DIGEST = _ACF_AUTHORIZATION_POLICY_DIGEST
_ADCFDA_SITE_POLICY_DIGEST = PAFD_SITE_POLICY_DIGEST
_ADCFDA_SIGNER_SITE_POLICY_DIGEST = _ADCF_SIGNER_SITE_POLICY_DIGEST
_ADCFDA_DECISION_SITE_POLICY_DIGEST = PFDA_DECISION_SITE_POLICY_DIGEST
_ADCFDA_AGGREGATE_DIGEST = PFDA_AGGREGATE_DIGEST

_ADCFDA_DIGEST_FIELDS = (
    _ADCFDA_PRUNE_POLICY_DIGEST,
    _ADCFDA_AUTHORIZATION_POLICY_DIGEST,
    _ADCFDA_SITE_POLICY_DIGEST,
    _ADCFDA_SIGNER_SITE_POLICY_DIGEST,
    _ADCFDA_DECISION_SITE_POLICY_DIGEST,
)

_ADCFDA_PAYLOAD_KEYS = frozenset((
    _ADCFDA_INPUTS,
    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    _ADCFDA_PRUNE_POLICY_DIGEST,
    _ADCFDA_AUTHORIZATION_POLICY_DIGEST,
    _ADCFDA_SITE_POLICY_DIGEST,
    _ADCFDA_SIGNER_SITE_POLICY_DIGEST,
    _ADCFDA_DECISION_SITE_POLICY_DIGEST,
    _ADCFDA_DECLARATION,
    STATUS,
    VERSION,
))
_ADCFDA_RESULT_KEYS = (
    _ADCFDA_AGGREGATE_DIGEST,
    _ADCFDA_INPUTS,
    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    _ADCFDA_PRUNE_POLICY_DIGEST,
    _ADCFDA_AUTHORIZATION_POLICY_DIGEST,
    _ADCFDA_SITE_POLICY_DIGEST,
    _ADCFDA_SIGNER_SITE_POLICY_DIGEST,
    _ADCFDA_DECISION_SITE_POLICY_DIGEST,
    _ADCFDA_DECLARATION,
    STATUS,
    VERSION,
)


def _verify_adcf_decision_core(
    decision: bytes,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_site_policy: dict,
    validated_signer_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one aggregate decision chain fork decision from materials.

    Shared core of :func:`verify_aggregate_decision_chain_fork_decision`
    and the batch :func:`verify_aggregate_decision_chain_fork_decisions`;
    the caller owns the argument-type and shared-material validation.
    The returned dict is freshly built solely from authenticated
    decision material.
    """
    payload, signature = _parse_adcf_decision(decision)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[PAFD_PRUNE_POLICY_DIGEST] != expected_prune_digest:
        raise _adcf_decision_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_authorization_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if payload[_ACF_DECISION_AUTHORIZATION_POLICY_DIGEST] != \
            expected_authorization_digest:
        raise _adcf_decision_invalid(
            "authorization policy digest does not match the authorization "
            "policy"
        )
    expected_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[_ADCF_SITE_POLICY_DIGEST] != expected_site_digest:
        raise _adcf_decision_invalid(
            "site policy digest does not match the fork-proof signer site "
            "policy"
        )
    expected_signer_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_signer_site_policy)
    ).hexdigest()
    if payload[_ADCF_SIGNER_SITE_POLICY_DIGEST] != expected_signer_digest:
        raise _adcf_decision_invalid(
            "signer site policy digest does not match the signer site policy"
        )

    # The proof digest vector is bound term by term to the canonical
    # (stably sorted) rows, so a reordering of the summaries that is then
    # re-signed is rejected even though the digest multiset is unchanged.
    status = _reconcile_pafd(
        payload, validated_signer_site_policy[ADJ_THRESHOLD],
        invalid=_adcf_decision_invalid, positional_proofs=True,
    )

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "aggregate decision chain fork decision signature does not match"
        )

    return {
        PAFD_COMMON: copy.deepcopy(payload[PAFD_COMMON]),
        FORK_PROOF_DIGEST: hashlib.sha256(decision).hexdigest(),
        VD_ISSUER: payload[VD_ISSUER],
        ITEMS: copy.deepcopy(payload[ITEMS]),
        KEY_VERSION: payload[KEY_VERSION],
        PAFD_PRUNE_POLICY_DIGEST: expected_prune_digest,
        PAFD_PROOFS: list(payload[PAFD_PROOFS]),
        _ACF_AUTHORIZATION_POLICY_DIGEST: expected_authorization_digest,
        _ADCF_SIGNER_SITE_POLICY_DIGEST: expected_signer_digest,
        _ADCF_SITE_POLICY_DIGEST: expected_site_digest,
        STATUS: status,
        VERSION: AGGREGATE_DECISION_CHAIN_FORK_DECISION_VERSION,
    }


def _adcf_decisions_item_report(
    item_id: str, status: str, error: str | None, result: dict | None
) -> dict:
    """One aggregate decision chain fork decision report, fixed order."""
    return {
        CHECKPOINT_ITEM_ERROR: error,
        ID: item_id,
        VERDICT_ITEM_RESULT: result,
        STATUS: status,
    }


def _verify_adcfd_decision_item(
    item: dict,
    validated_prune_policy: dict,
    validated_authorization_policy: dict,
    validated_site_policy: dict,
    validated_signer_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify one aggregate decision chain fork decision in isolation.

    Unknown, revoked, not-yet-valid or expired credentials and a wrong
    signature make the item ``unauthenticated``; every encoding,
    key-set, digest, ordering, tally or binding fault makes it
    ``invalid-decision``; a passing decision is ``verified``.
    """
    item_id = item[ID]
    try:
        result = _verify_adcf_decision_core(
            item[_CFD_DECISION],
            validated_prune_policy,
            validated_authorization_policy,
            validated_site_policy,
            validated_signer_site_policy,
            validated_keyring,

def _reject_duplicate_pafd_keys(pairs: list[tuple], invalid=_pafd_invalid) -> dict:
    """``object_pairs_hook`` turning duplicate decision keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _pac_fork_edge_object(entry: dict) -> dict:
    """One canonical ``{rootDigest, predecessorDigest, successors}`` edge."""
    return {
        PAC_ROOT_DIGEST: entry[PAC_ROOT_DIGEST],
        PAC_PREDECESSOR_DIGEST: entry[PAC_PREDECESSOR_DIGEST],
        PAC_BATCH_SUCCESSORS: list(entry[PAC_BATCH_SUCCESSORS]),
    }


def _pac_fork_proof_edges(payload: dict) -> list[dict]:
    """The complete fork edge set a verified fork proof binds.

    The proof parser already validated every fork entry, its ordering
    and its successor set, so the entries are copied verbatim in the
    report's own canonical (root, predecessor, successor) order.
    """
    return [
        _pac_fork_edge_object(fork)
        for fork in payload[FORK_PROOF_REPORT][CHAINS_FORKS]
    ]


def _pac_fork_edge_triples(
    edges: list[dict],
) -> tuple[tuple[str, str, tuple[str, ...]], ...]:
    """Order-preserving edge objects to comparable triples."""
    return tuple(
        (
            edge[PAC_ROOT_DIGEST],
            edge[PAC_PREDECESSOR_DIGEST],
            tuple(edge[PAC_BATCH_SUCCESSORS]),
        )
        for edge in edges
    )


def _sorted_pac_fork_edge_objects(
    triples: set | frozenset,
) -> list[dict]:
    """Unique fork edges sorted by (rootDigest, predecessorDigest, ...)."""
    return [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: list(successors),
        }
        for root_digest, predecessor, successors in sorted(triples)
    ]


def _validated_pafd_edge(value: object, where: str, invalid=_pafd_invalid) -> dict:
    """Validate one bound fork edge object into a fresh ordered dict.

    Every non-type structural fault is raised through ``invalid`` (the
    prune aggregate fork decision error by default), so the same
    validation backs the chain fork decision packet.
    """
    if not isinstance(value, dict):
        raise TypeError(f"{where} edge must be an object")
    if set(value.keys()) != _PAFD_EDGE_KEYS:
        raise invalid(
            f"{where} edge must contain exactly the keys 'predecessorDigest', "
            "'rootDigest' and 'successors'"
        )
    root_digest = value[PAC_ROOT_DIGEST]
    predecessor = value[PAC_PREDECESSOR_DIGEST]
    successors = value[PAC_BATCH_SUCCESSORS]
    if not isinstance(root_digest, str):
        raise TypeError(f"{where} edge rootDigest must be a str")
    if not isinstance(predecessor, str):
        raise TypeError(f"{where} edge predecessorDigest must be a str")
    if not _prune_is_digest(root_digest):
        raise invalid(
            f"{where} edge rootDigest must be 64 lowercase hex characters"
        )
    if not _prune_is_digest(predecessor):
        raise invalid(
            f"{where} edge predecessorDigest must be 64 lowercase hex "
            "characters"
        )
    if not isinstance(successors, list):
        raise TypeError(f"{where} edge successors must be a list")
    if not successors:
        raise invalid(f"{where} edge successors must be non-empty")
    for position, successor in enumerate(successors):
        if not isinstance(successor, str):
            raise TypeError(
                f"{where} edge successor {position} must be a str"
            )
        if not _prune_is_digest(successor):
            raise invalid(
                f"{where} edge successor {position} must be 64 lowercase "
                "hex characters"
            )
    if successors != sorted(successors) or len(set(successors)) != len(
        successors
    ):
        raise invalid(
            f"{where} edge successors must be unique and sorted ascending"
        )
    return {
        PAC_ROOT_DIGEST: root_digest,
        PAC_PREDECESSOR_DIGEST: predecessor,
        PAC_BATCH_SUCCESSORS: list(successors),
    }


def _pafd_row(
    item_id: str,
    proof_digest: str,
    site: str | None,
    key_version: int | None,
    edges: list[dict] | None,
    conclusion: str,
    reason: str | None,
) -> dict:
    """One per-proof decision row with the fixed bound key set."""
    return {
        ADJ_CONCLUSION: conclusion,
        PAFD_EDGES: edges,
        ID: item_id,
        KEY_VERSION: key_version,
        PAFD_FORK_PROOF_DIGEST: proof_digest,
        ADJ_REASON: reason,
        VD_ISSUER: site,
    }


def _adjudicate_pac_fork_one(
    item: dict,
    prune_policy_digest: str,
    site_policy: dict,
    keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify, authorize and authenticate one fork proof in isolation.

    The proof is first checked through the exact
    :func:`verify_prune_aggregate_fork_proof` structural rules, then the
    signing site and key version are authorized exactly against the site
    policy with no fallback, and finally the HMAC is checked against the
    current keyring.  Any failure rejects just this row with one fixed
    reason and never affects the other items.
    """
    item_id = item[ID]
    raw_proof = item[FORK_PROOF_ITEM_PROOF]
    proof_digest = hashlib.sha256(raw_proof).hexdigest()

    def structural_invalid() -> dict:
        return _pafd_row(
            item_id, proof_digest, None, None, None,
            _PAFD_CONCLUSION_INVALID, _PAFD_REASON_INVALID_PROOF,
        )

    try:
        payload, signature, _chains = _parse_pac_fork_proof(raw_proof)
    except (TypeError, ValueError):
        return structural_invalid()

    site = payload[VD_ISSUER]
    key_version = payload[KEY_VERSION]
    try:
        edges = _pac_fork_proof_edges(payload)
    except (TypeError, ValueError):
        return structural_invalid()

    def reject(reason: str) -> dict:
        return _pafd_row(
            item_id, proof_digest, site, key_version, edges,
            _PAFD_CONCLUSION_INVALID, reason,
        )

    # The proof must be bound to the exact shared prune policy and must
    # not be dated after the adjudication moment; a mismatch makes the
    # claimed identity untrustworthy, so the row carries none.
    if payload[RECEIPT_POLICY] != prune_policy_digest:
        return structural_invalid()
    if payload[CP_MOMENT] > moment:
        return structural_invalid()

    allowed_versions = site_policy[ADJ_SITES].get(site)
    if allowed_versions is None:
        return reject(REASON_UNAUTHORIZED_SITE)
    if key_version not in allowed_versions:
        return reject(REASON_UNAUTHORIZED_VERSION)

    key_entry = None
    for candidate in keyring.get(site, ()):
        if candidate[VERSION] == key_version:
            key_entry = candidate
            break
    if key_entry is None:
        return reject(REASON_CREDENTIAL_UNAVAILABLE)
    if key_entry[REVOKED]:
        return reject(REASON_REVOKED)
    if moment < key_entry[NOT_BEFORE]:
        return reject(REASON_NOT_YET_VALID)
    if moment > key_entry[NOT_AFTER]:
        return reject(REASON_EXPIRED)

    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        return reject(REASON_BAD_SIGNATURE)

    return _pafd_row(
        item_id, proof_digest, site, key_version, edges,
        _PAFD_CONCLUSION_VALID, None,
    )


_PAFD_EDGE_SET = frozenset[tuple[str, str, tuple[str, ...]]]


def _pafd_content(row: dict) -> _PAFD_EDGE_SET:
    """The complete fork edge set one authenticated row declares."""
    return frozenset(_pac_fork_edge_triples(row[PAFD_EDGES]))


def _tally_pac_fork_rows(
    rows: list[dict],
) -> tuple[bool, dict[str, _PAFD_EDGE_SET]]:
    """Group authenticated rows per site by their complete edge sets.

    Two rows from one site are the same declaration only when their
    complete fork edge set -- every ``(rootDigest, predecessorDigest,
    successors)`` triple -- agrees, regardless of the proof digest.
    The smallest-id row of one identical set is the vote and extras are
    ``duplicate``, while two distinct edge sets from one site are both a
    ``contradiction``.  Returns ``(contradicted, votes)`` where
    ``votes`` maps each non-contradicting site to its one edge set.
    """
    by_site: dict[str, dict[_PAFD_EDGE_SET, list[dict]]] = {}
    for row in rows:
        if row[ADJ_CONCLUSION] in (
            _PAFD_CONCLUSION_VALID,
            _PAFD_CONCLUSION_DUPLICATE,
            _PAFD_CONCLUSION_CONTRADICTION,
        ):
            by_site.setdefault(row[VD_ISSUER], {}).setdefault(
                _pafd_content(row), []
            ).append(row)

    contradicted = False
    votes: dict[str, _PAFD_EDGE_SET] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            ordered_groups = sorted(
                groups.values(),
                key=lambda members: min(member[ID] for member in members),
            )
            for members in ordered_groups:
                members.sort(key=lambda row: row[ID])
                members[0][ADJ_CONCLUSION] = _PAFD_CONCLUSION_CONTRADICTION
                members[0][ADJ_REASON] = REASON_CONTRADICTION
                for extra in members[1:]:
                    extra[ADJ_CONCLUSION] = _PAFD_CONCLUSION_DUPLICATE
                    extra[ADJ_REASON] = REASON_DUPLICATE
        else:
            content, members = next(iter(groups.items()))
            members.sort(key=lambda row: row[ID])
            members[0][ADJ_CONCLUSION] = _PAFD_CONCLUSION_VALID
            members[0][ADJ_REASON] = None
            for extra in members[1:]:
                extra[ADJ_CONCLUSION] = _PAFD_CONCLUSION_DUPLICATE
                extra[ADJ_REASON] = REASON_DUPLICATE
            votes[site] = content
    return contradicted, votes


def adjudicate_prune_aggregate_forks(
    items, prune_policy, site_policy, keyring, moment, issuer, version
):
    """Adjudicate multi-site prune aggregate fork proofs offline.

    ``items`` is a non-empty list; each item contains exactly a unique
    non-empty ``id`` and ``proof`` bytes produced by
    :func:`sign_prune_aggregate_fork_proof`.  ``prune_policy`` is the
    shared invariant original ``{"batch","sites","threshold"}`` pruning
    policy the proofs were issued against; ``site_policy`` carries
    exactly ``sites`` (a non-empty map of each authorized non-empty site
    to its non-empty set of allowed positive key versions) and
    ``threshold`` (a positive integer no greater than the site count).
    ``keyring`` follows the existing rules, ``moment`` is the
    non-negative adjudication moment and ``issuer``/``version`` name the
    adjudicator credentials.  No file is read or written and no input is
    modified.

    Every proof is first verified through the existing prune aggregate
    fork proof rules, then authorized by the exact signing site and key
    version its payload names with no fallback, then authenticated
    against the current keyring.  An invalid, unauthenticated or
    unauthorized proof rejects just that item with one fixed reason
    (``invalid-proof``, ``unauthorized-site``, ``unauthorized-version``,
    ``credential-unavailable``, ``revoked``, ``not-yet-valid``,
    ``expired`` or ``bad-signature``) while the later items are still
    processed.  For one site the complete fork edge set counts once --
    extra proofs declaring an identical edge set are ``duplicate`` --
    while distinct valid edge sets from one site are a
    ``contradiction``.  Distinct sites must agree exactly on the
    complete fork edge set made of the root digest, the forking
    predecessor digest and the sorted legal successor digests; any
    contradiction or cross-site disagreement is ``conflicted`` with a
    null common edge set and no majority can outvote it.  A unique edge
    set backed by at least the threshold of distinct sites is
    ``accepted``; the same unique set short of the threshold stays

def _reconcile_pafd(
    payload: dict, threshold: int, invalid=_pafd_invalid,
    positional_proofs: bool = False,
) -> str:
    """Re-derive every aggregate binding of a parsed fork decision.

    Re-tallies the per-proof rows the signature covers -- row ordering,
    proof digests, duplicate/contradiction conclusions, the cross-site
    complete-edge-set agreement, the threshold acceptance and the
    claimed common set -- without seeing any fork proof.  Any mismatch
    raises :class:`InvalidAggregateForkDecisionError`; otherwise the
    derived status is returned.

    With ``positional_proofs`` the bound ``proofs`` vector must match the
    sorted per-row digests term by term (so a reordering that is then
    re-signed is rejected); otherwise the two digest multisets only must
    agree.
    """
    rows = payload[ITEMS]
    proofs = payload[PAFD_PROOFS]
    if len(rows) != len(proofs):
        raise invalid(
            "the items must cover every proof and vice versa"
        )
    expected_order = sorted(
        rows,
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        ),
    )
    if [row[ID] for row in expected_order] != [row[ID] for row in rows]:
        raise invalid("items must be sorted by site then id")
    row_digests = [row[PAFD_FORK_PROOF_DIGEST] for row in rows]
    if positional_proofs:
        if row_digests != proofs:
            raise invalid(
                "the bound proof digests must correspond term by term to "
                "the sorted items"
            )
    elif sorted(row_digests) != sorted(proofs):
        raise invalid(
            "the bound proof digests must equal the per-item digests"
        )

    by_site: dict[str, dict[_PAFD_EDGE_SET, list[dict]]] = {}
    for row in rows:
        if row[ADJ_CONCLUSION] == _PAFD_CONCLUSION_INVALID:
            continue
        by_site.setdefault(row[VD_ISSUER], {}).setdefault(
            _pafd_content(row), []
        ).append(row)

    contradicted = False
    votes: dict[str, _PAFD_EDGE_SET] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            expected_conclusion = _PAFD_CONCLUSION_CONTRADICTION
            expected_reason = REASON_CONTRADICTION
        else:
            expected_conclusion = _PAFD_CONCLUSION_VALID
            expected_reason = None
            votes[site] = next(iter(groups.keys()))
        for members_raw in groups.values():
            members = sorted(members_raw, key=lambda row: row[ID])
            for index, row in enumerate(members):
                if index == 0:
                    if row[ADJ_CONCLUSION] != expected_conclusion:
                        raise invalid(
                            f"item {row[ID]!r} has the wrong conclusion"
                        )
                    if row[ADJ_REASON] != expected_reason:
                        raise invalid(
                            f"item {row[ID]!r} has the wrong reason"
                        )
                else:
                    if row[ADJ_CONCLUSION] != _PAFD_CONCLUSION_DUPLICATE:
                        raise invalid(
                            f"item {row[ID]!r} must be a duplicate"
                        )
                    if row[ADJ_REASON] != REASON_DUPLICATE:
                        raise invalid(
                            f"item {row[ID]!r} must carry the duplicate "
                            "reason"
                        )
            representative = members[0]
            for row in members[1:]:
                if _pac_fork_edge_triples(
                    row[PAFD_EDGES]
                ) != _pac_fork_edge_triples(representative[PAFD_EDGES]):
                    raise invalid(
                        f"item {row[ID]!r} duplicates a proof with a "
                        "different fork edge set"
                    )

    edge_sets = set(votes.values())
    if contradicted or len(edge_sets) > 1:
        status = _PAFD_STATUS_CONFLICTED
        expected_common = None
    elif len(edge_sets) == 1 and len(votes) >= threshold:
        status = _PAFD_STATUS_ACCEPTED
        expected_common = _sorted_pac_fork_edge_objects(
            next(iter(edge_sets))
        )
    elif len(edge_sets) == 1:
        status = _PAFD_STATUS_INSUFFICIENT
        expected_common = _sorted_pac_fork_edge_objects(
            next(iter(edge_sets))
        )
    else:
        status = _PAFD_STATUS_INSUFFICIENT
        expected_common = None

    if payload[STATUS] != status:
        raise invalid("the status does not match the tallied items")
    if payload[PAFD_COMMON] != expected_common:
        raise invalid(
            "the bound common edge set does not match the tallied items"
        )
    return status


def verify_prune_aggregate_fork_decision(
    decision, prune_policy, site_policy, keyring, moment
):
    """Re-verify a signed prune aggregate fork decision entirely offline.

    Only the decision bytes, the expected shared ``prune_policy``, the
    expected ``site_policy``, the current ``keyring`` and the
    verification ``moment`` are consulted -- no file is read or written
    and no argument is modified.  Verification validates the canonical
    encoding and every key set, recomputes both policy digests, re-tallies
    the bound per-proof rows purely from the signed payload (the
    original-order proof digest bindings, the site/id row ordering, the
    same-site duplicate/contradiction markings, the cross-site complete
    fork-edge-set agreement, the threshold outcome and the claimed
    common set), and checks the HMAC-SHA256 against the key the *current*
    keyring binds to the payload's exact issuer and version, usable at
    the verification moment, so a later revocation or expiry rejects
    the decision with no fallback.

    On success a fresh mapping is returned with the fixed keys
    ``common``, ``decisionDigest`` (the SHA-256 of the decision bytes),
    ``issuer``, ``items``, ``keyVersion``, ``prunePolicyDigest``,
    ``proofs``, ``sitePolicyDigest``, ``status`` and ``version`` (the
    integer 1).  A non-bytes decision or a public field of the wrong
    type raises :class:`TypeError` (a :class:`bool` never poses as an
    int); an illegal prune/site policy, keyring or moment raises
    :class:`ValueError`; an illegal encoding, key set, digest, ordering,
    tally or binding raises
    :class:`InvalidAggregateForkDecisionError` (a :class:`ValueError`
    subclass); unknown, revoked, not-yet-valid or expired credentials
    or a signature mismatch raise :class:`AuthenticationError`.
    """
    if not isinstance(decision, bytes):
        raise TypeError("decision must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")
    return _verify_pafd_core(
        decision, validated_prune_policy, validated_site_policy,
        validated_keyring, verify_moment,
    )


def _verify_pafd_core(
    decision: bytes,
    validated_prune_policy: dict,
    validated_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one fork decision against already-validated shared materials.

    This is the shared core of
    :func:`verify_prune_aggregate_fork_decision` and the batch
    :func:`verify_prune_aggregate_fork_decisions`; the caller owns the
    argument-type and shared-material validation.  The returned dict is
    freshly built solely from authenticated decision material.
    """
    payload, signature = _parse_pafd(decision)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[PAFD_PRUNE_POLICY_DIGEST] != expected_prune_digest:
        raise _pafd_invalid("prune policy digest does not match the policy")
    expected_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[PAFD_SITE_POLICY_DIGEST] != expected_site_digest:
        raise _pafd_invalid("site policy digest does not match the policy")

    status = _reconcile_pafd(
        payload, validated_site_policy[ADJ_THRESHOLD]
    )

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "prune aggregate fork decision signature does not match"
        )

    return {
        key: copy.deepcopy(value)
        for key, value in (
            (PAFD_COMMON, payload[PAFD_COMMON]),
            (FORK_PROOF_DIGEST, hashlib.sha256(decision).hexdigest()),
            (VD_ISSUER, payload[VD_ISSUER]),
            (ITEMS, payload[ITEMS]),
            (KEY_VERSION, payload[KEY_VERSION]),
            (PAFD_PRUNE_POLICY_DIGEST, expected_prune_digest),
            (PAFD_PROOFS, payload[PAFD_PROOFS]),
            (PAFD_SITE_POLICY_DIGEST, expected_site_digest),
            (STATUS, status),
            (VERSION, PRUNE_AGGREGATE_FORK_DECISION_VERSION),
        )
    }


